import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Button, Card, Spin, Typography, Row, Col, Tag, Space, Progress } from 'antd';
import { ArrowLeftOutlined, ReloadOutlined } from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import request from '../utils/request';

const { Title, Text } = Typography;

const SIGNAL_TAG = {
  extreme_fear: { color: 'green', label: '极端恐惧' },
  bottom: { color: 'green', label: '底部信号' },
  caution: { color: 'orange', label: '谨慎' },
  neutral: { color: 'default', label: '中性' },
  overheat: { color: 'red', label: '过热' },
};

const SOURCE_LABEL = {
  sina: '新浪财经',
  tiger: '老虎行情',
  futu: '富途 OpenD',
  eastmoney: '东方财富',
  yahoo: 'Yahoo Finance',
  fred: 'FRED（联储）',
};

/** 主指标数值语义（但斌框架；API value_hint 优先） */
const VALUE_KIND_LABEL = {
  price: '',
  drawdown_from_high: '距高点回撤',
  ratio: '比值',
  spread: '日强弱差',
  breadth_spread: '等权相对市值加权',
  level: '',
  flow: '周净流入/累计',
  allocation: '股票配置比例',
};

/** 副栏涨跌语义（API change_hint 优先） */
const CHANGE_KIND_LABEL = {
  daily: '日涨跌',
  drawdown_delta: '回撤变化',
  period: '较上期',
  fred_period: '较上一发布日',
  daily_period: '较上一交易日',
  weekly: '周环比',
  monthly: '较上期',
  term_structure_delta: '期限结构变化',
};

function valueKindLabel(it) {
  if (it.value_hint) return it.value_hint;
  const kind = it.value_kind;
  if (!kind || kind === 'price' || kind === 'level') return '';
  return VALUE_KIND_LABEL[kind] || '';
}

function changeKindLabel(it) {
  if (it.change_hint) return it.change_hint;
  const kind = it.change_kind;
  if (kind === 'none') return '';
  if (!kind) return '日涨跌';
  return CHANGE_KIND_LABEL[kind] || '变动';
}

function shouldShowChange(it, pct) {
  if (it.change_kind === 'none') return false;
  return pct != null && Number.isFinite(Number(pct));
}

function changeColor(pct) {
  if (pct == null || Number.isNaN(pct)) return '#AEAEB2';
  if (pct > 0.01) return '#FF3B30';
  if (pct < -0.01) return '#34C759';
  return '#8E8E93';
}

function pctBarWidth(pct) {
  if (pct == null || Number.isNaN(pct)) return 0;
  const w = Math.min(100, Math.abs(pct) * 8);
  return Math.round(w);
}

function fmtValue(v, unit) {
  if (v == null || !Number.isFinite(Number(v))) return '';
  const n = Number(v);
  if (unit === '%') return `${n.toFixed(2)}%`;
  if (unit === '亿元') return n >= 10000 ? `${(n / 10000).toFixed(2)} 万亿` : `${n.toFixed(0)} 亿`;
  if (Math.abs(n) >= 1000) return n.toFixed(2);
  if (Math.abs(n) >= 1) return n.toFixed(4);
  return n.toFixed(5);
}

function synthesisStrokeColor(score) {
  if (score == null || Number.isNaN(score)) return '#007AFF';
  if (score <= 30) return '#34C759';
  if (score >= 70) return '#FF3B30';
  return '#007AFF';
}

function IndicatorBoard() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [updatedAt, setUpdatedAt] = useState('');
  const [indicators, setIndicators] = useState([]);
  const [synthesis, setSynthesis] = useState(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await request('/api/fund-temperature/indicator-board', { method: 'GET' });
      if (res && res.data) {
        setUpdatedAt(res.data.updated_at || '');
        setIndicators(Array.isArray(res.data.indicators) ? res.data.indicators : []);
        setSynthesis(res.data.synthesis || null);
      } else {
        setIndicators([]);
        setSynthesis(null);
      }
    } catch {
      setIndicators([]);
      setSynthesis(null);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const byCategory = useMemo(() => {
    const m = new Map();
    for (const it of indicators) {
      const c = it.category || '其它';
      if (!m.has(c)) m.set(c, []);
      m.get(c).push(it);
    }
    return Array.from(m.entries());
  }, [indicators]);

  return (
    <div className="equation-indicator-board-page equation-tab-page" style={{ background: '#F2F2F7' }}>
      <div className="equation-page-inner" style={{ maxWidth: 1200, margin: '0 auto', padding: '16px' }}>
        <Space direction="vertical" size="middle" style={{ width: '100%' }}>
          <Row align="middle" justify="space-between" wrap={false} gutter={8}>
            <Col flex="none">
              <Button type="text" icon={<ArrowLeftOutlined />} onClick={() => navigate('/fund-temperature')}>
                返回
              </Button>
            </Col>
            <Col flex="auto" style={{ textAlign: 'center' }}>
              <Title level={4} style={{ margin: 0, fontSize: 20, fontWeight: 700, color: '#1C1C1E' }}>
                指标大盘
              </Title>
            </Col>
            <Col flex="none">
              <Button type="link" icon={<ReloadOutlined />} onClick={load} disabled={loading}>
                刷新
              </Button>
            </Col>
          </Row>
          {updatedAt ? (
            <Text type="secondary" style={{ fontSize: 12 }}>
              更新时间 {updatedAt}
            </Text>
          ) : null}

          {!loading && synthesis && synthesis.regime ? (
            <Card size="small" styles={{ body: { padding: 16 } }}>
              <Row gutter={[16, 12]} align="middle">
                <Col xs={24} sm={8} style={{ textAlign: 'center' }}>
                  <Progress
                    type="dashboard"
                    percent={synthesis.score ?? 50}
                    format={(p) => `${p}`}
                    strokeColor={synthesisStrokeColor(synthesis.score)}
                    size={100}
                  />
                  <div>
                    <Text type="secondary" style={{ fontSize: 11 }}>
                      0 恐惧 ← → 100 贪婪
                    </Text>
                  </div>
                </Col>
                <Col xs={24} sm={16}>
                  <Text strong style={{ fontSize: 16 }}>
                    {synthesis.regime}
                  </Text>
                  {Array.isArray(synthesis.highlights) && synthesis.highlights.length > 0 ? (
                    <ul style={{ margin: '8px 0 0', paddingLeft: 18, fontSize: 13, color: '#636366' }}>
                      {synthesis.highlights.map((h) => (
                        <li key={h} style={{ marginBottom: 4 }}>
                          {h}
                        </li>
                      ))}
                    </ul>
                  ) : null}
                  <Text type="secondary" style={{ fontSize: 11, display: 'block', marginTop: 8 }}>
                    综合读数以 VIX 为主轴，并结合回撤中位数与其它情绪信号；回撤类指标不重复计分；数据缓存 11 分钟
                  </Text>
                </Col>
              </Row>
            </Card>
          ) : null}

          {loading ? (
            <div style={{ textAlign: 'center', padding: 48 }}>
              <Spin size="large" />
            </div>
          ) : (
            byCategory.map(([category, list]) => {
              return (
                <Card key={category} title={category} size="small" styles={{ body: { padding: 12 } }}>
                  <Space direction="vertical" size="small" style={{ width: '100%' }}>
                    {list.map((it) => {
                      const has = it.source && it.source !== 'none' && it.value != null;
                      const pct = it.change_percent;
                      const showChange = has && shouldShowChange(it, pct);
                      const barW = showChange ? pctBarWidth(pct) : 0;
                      const valueHint = valueKindLabel(it);
                      const changeHint = changeKindLabel(it);
                      const sigMeta = it.signal_level ? SIGNAL_TAG[it.signal_level] : null;
                      return (
                        <div
                          key={it.id}
                          style={{
                            borderBottom: '0.5px solid #E5E5EA',
                            paddingBottom: 10,
                            marginBottom: 4,
                          }}
                        >
                          <Row gutter={[8, 4]} align="middle">
                            <Col xs={24} sm={10} md={8}>
                              <Text strong>{it.name}</Text>
                              {it.signal ? (
                                <div style={{ marginTop: 4 }}>
                                  <Tag color={sigMeta?.color || 'blue'} style={{ margin: 0, fontSize: 11 }}>
                                    {it.signal}
                                  </Tag>
                                </div>
                              ) : null}
                              {it.note ? (
                                <div>
                                  <Text type="secondary" style={{ fontSize: 12 }}>
                                    {it.note}
                                  </Text>
                                </div>
                              ) : null}
                            </Col>
                            <Col xs={14} sm={8} md={6}>
                              {has ? (
                                <Space align="baseline" wrap direction="vertical" size={0}>
                                  <Space align="baseline" wrap>
                                    <Text style={{ fontSize: 18 }}>{fmtValue(it.value, it.unit)}</Text>
                                    {it.unit && it.unit !== '%' && it.unit !== '亿元' ? (
                                      <Text type="secondary" style={{ fontSize: 12 }}>
                                        {it.unit}
                                      </Text>
                                    ) : null}
                                  </Space>
                                  {valueHint ? (
                                    <Text type="secondary" style={{ fontSize: 11 }}>
                                      {valueHint}
                                    </Text>
                                  ) : null}
                                </Space>
                              ) : (
                                <Space direction="vertical" size={0}>
                                  <Text type="secondary">无数据源</Text>
                                  {valueHint ? (
                                    <Text type="secondary" style={{ fontSize: 11 }}>
                                      主值：{valueHint}
                                    </Text>
                                  ) : null}
                                  {changeHint ? (
                                    <Text type="secondary" style={{ fontSize: 11 }}>
                                      副栏：{changeHint}
                                    </Text>
                                  ) : null}
                                </Space>
                              )}
                            </Col>
                            <Col xs={10} sm={6} md={5} style={{ textAlign: 'right' }}>
                              {showChange ? (
                                <Tag color={pct >= 0 ? 'red' : 'green'} style={{ margin: 0 }}>
                                  {pct >= 0 ? '+' : ''}
                                  {Number(pct).toFixed(2)}%
                                </Tag>
                              ) : has && it.change_kind !== 'none' ? (
                                <Text type="secondary">—</Text>
                              ) : null}
                            </Col>
                            <Col xs={24} md={5}>
                              {showChange ? (
                                <div style={{ marginTop: 4 }}>
                                  <div
                                    style={{
                                      height: 6,
                                      borderRadius: 3,
                                      background: '#f0f0f0',
                                      overflow: 'hidden',
                                    }}
                                  >
                                    <div
                                      style={{
                                        width: `${barW}%`,
                                        height: '100%',
                                        background: changeColor(pct),
                                      }}
                                    />
                                  </div>
                                  {changeHint ? (
                                    <Text type="secondary" style={{ fontSize: 11 }}>
                                      {changeHint}
                                    </Text>
                                  ) : null}
                                </div>
                              ) : null}
                            </Col>
                          </Row>
                          {has ? (
                            <div style={{ marginTop: 4 }}>
                              <Text type="secondary" style={{ fontSize: 11 }}>
                                来源：{SOURCE_LABEL[it.source] || it.source}
                              </Text>
                            </div>
                          ) : null}
                        </div>
                      );
                    })}
                  </Space>
                </Card>
              );
            })
          )}
        </Space>
      </div>
    </div>
  );
}

export default IndicatorBoard;
