const DEVICE_ID_KEY = 'equation_device_id';
const DEVICE_ID_PATTERN = /^[a-zA-Z0-9_-]{8,64}$/;

// getOrCreateDeviceId 浏览器本地持久设备 ID；Chrome 升级通常保留 localStorage，可区分不同电脑。
export function getOrCreateDeviceId() {
  try {
    const existing = localStorage.getItem(DEVICE_ID_KEY);
    if (existing && DEVICE_ID_PATTERN.test(existing)) {
      return existing;
    }
    const id =
      typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function'
        ? crypto.randomUUID()
        : `d_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 12)}`;
    localStorage.setItem(DEVICE_ID_KEY, id);
    return id;
  } catch (e) {
    // 无 localStorage（隐私模式极端情况）时每次登录都可能算新设备
    return `tmp_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 12)}`;
  }
}
