import React, { useEffect, useCallback, useState } from 'react';
import { Tag, Button, message } from 'antd';
import { ArrowLeftOutlined, ReloadOutlined, CopyOutlined } from '@ant-design/icons';
import { useNavigate, useSearchParams } from 'react-router-dom';

function HoldingChangeDetail() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const entity = searchParams.get('entity');
  const keyword = searchParams.get('keyword'); // 从URL参数获取keyword
  const [showKeyword, setShowKeyword] = useState(true);

  // 优先使用keyword参数，如果没有则使用entity
  const searchKeyword = keyword || entity || '';
  
  // 尝试多种URL参数格式
  const doubaoUrl = searchKeyword 
    ? `https://www.doubao.com/chat?q=${encodeURIComponent(searchKeyword)}&query=${encodeURIComponent(searchKeyword)}&text=${encodeURIComponent(searchKeyword)}`
    : 'https://www.doubao.com/chat';

  const handleReload = useCallback(() => {
    const iframe = document.getElementById('doubao-iframe');
    if (iframe) {
      // 重新加载iframe：先保存当前src，然后重新设置
      const currentSrc = iframe.src;
      iframe.src = '';
      setTimeout(() => {
        if (iframe) {
          iframe.src = currentSrc;
        }
      }, 0);
    }
  }, []);

  const handleCopyKeyword = useCallback(() => {
    if (searchKeyword) {
      navigator.clipboard.writeText(searchKeyword).then(() => {
        message.success('搜索关键词已复制到剪贴板，请粘贴到豆包输入框');
      }).catch(() => {
        message.error('复制失败，请手动复制');
      });
    }
  }, [searchKeyword]);

  // 尝试在iframe加载后自动填充（可能因为跨域限制无法工作，但尝试一下）
  useEffect(() => {
    if (!searchKeyword) return;

    const iframe = document.getElementById('doubao-iframe');
    if (!iframe) return;

    const tryFillInput = () => {
      try {
        const iframeDoc = iframe.contentDocument || iframe.contentWindow?.document;
        if (!iframeDoc) return;

        // 尝试多种选择器来找到输入框
        const selectors = [
          'input[type="text"]',
          'textarea',
          'input[placeholder*="消息"]',
          'input[placeholder*="输入"]',
          'input[placeholder*="搜索"]',
          '.input',
          '#input',
          '[contenteditable="true"]'
        ];

        for (const selector of selectors) {
          const input = iframeDoc.querySelector(selector);
          if (input) {
            if (input.tagName === 'INPUT' || input.tagName === 'TEXTAREA') {
              input.value = searchKeyword;
              input.dispatchEvent(new Event('input', { bubbles: true }));
              input.dispatchEvent(new Event('change', { bubbles: true }));
            } else if (input.contentEditable === 'true') {
              input.textContent = searchKeyword;
              input.dispatchEvent(new Event('input', { bubbles: true }));
            }
            break;
          }
        }
      } catch (error) {
        // 跨域限制，无法访问iframe内容
        console.log('无法自动填充（跨域限制）:', error);
      }
    };

    // 等待iframe加载完成
    iframe.addEventListener('load', () => {
      setTimeout(tryFillInput, 1000);
    });
  }, [searchKeyword]);

  return (
    <div style={{ 
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      width: '100%',
      height: '100%',
      display: 'flex',
      flexDirection: 'column',
      background: '#fff',
      zIndex: 2000,
      boxSizing: 'border-box',
      paddingTop: 'env(safe-area-inset-top, 0px)',
      paddingBottom: 'env(safe-area-inset-bottom, 0px)',
      paddingLeft: 'env(safe-area-inset-left, 0px)',
      paddingRight: 'env(safe-area-inset-right, 0px)'
    }}>
      {/* 返回按钮和标题栏 */}
      <div style={{ 
        padding: '12px 16px',
        background: '#fff',
        borderBottom: '1px solid #E5E5EA',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        flexShrink: 0,
        zIndex: 1
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <Button 
            icon={<ArrowLeftOutlined />} 
            onClick={() => navigate('/risk-control', { replace: true })}
            size="small"
          >
            返回
          </Button>
          {entity && (
            <Tag color="blue" style={{ margin: 0 }}>
              {entity}
            </Tag>
          )}
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          {searchKeyword && (
            <Button 
              icon={<CopyOutlined />} 
              onClick={handleCopyKeyword}
              size="small"
              type="text"
            >
              复制关键词
            </Button>
          )}
          <Button 
            icon={<ReloadOutlined />} 
            onClick={handleReload}
            size="small"
            type="text"
          >
            刷新
          </Button>
        </div>
      </div>

      {/* 搜索关键词提示（可折叠） */}
      {searchKeyword && showKeyword && (
        <div style={{ 
          padding: '12px 16px',
          background: '#f0f7ff',
          borderBottom: '1px solid #e6f4ff',
          flexShrink: 0,
          zIndex: 1
        }}>
          <div style={{ 
            fontSize: '13px', 
            color: '#8E8E93', 
            marginBottom: '8px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between'
          }}>
            <span>搜索关键词（已自动填充到URL，如未生效请手动复制粘贴）：</span>
            <Button 
              type="text" 
              size="small"
              onClick={() => setShowKeyword(false)}
              style={{ padding: '0 4px', minWidth: 'auto' }}
            >
              ✕
            </Button>
          </div>
          <div style={{ 
            background: '#fff',
            padding: '8px 12px',
            borderRadius: '4px',
            border: '1px solid #d9d9d9',
            fontSize: '14px',
            color: '#333',
            wordBreak: 'break-all'
          }}>
            {searchKeyword}
          </div>
          <Button 
            icon={<CopyOutlined />} 
            onClick={handleCopyKeyword}
            size="small"
            type="primary"
            style={{ marginTop: '8px' }}
          >
            复制关键词
          </Button>
        </div>
      )}

      {/* 豆包iframe嵌入 */}
      <div style={{ 
        flex: 1,
        width: '100%',
        height: '100%',
        position: 'relative',
        overflow: 'hidden',
        minHeight: 0
      }}>
        <iframe
          id="doubao-iframe"
          src={doubaoUrl}
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            border: 'none',
            display: 'block'
          }}
          title="豆包搜索"
          allow="clipboard-read; clipboard-write"
          sandbox="allow-same-origin allow-scripts allow-forms allow-popups allow-popups-to-escape-sandbox"
        />
      </div>
    </div>
  );
}

export default HoldingChangeDetail;

