import React, { useCallback, useEffect, useState } from 'react';
import { Button, Card, Input, Space, Table, Tag, message } from 'antd';
import { ArrowLeftOutlined, ReloadOutlined } from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import request from '../utils/request';

const PAGE_SIZE = 15;

function formatTime(value) {
  if (!value) return '-';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return value;
  return d.toLocaleString('zh-CN', { hour12: false });
}

function formatDate(value) {
  if (!value) return '-';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return String(value).slice(0, 10);
  return d.toLocaleDateString('zh-CN').replace(/\//g, '-');
}

function formatPct(v) {
  if (v == null || Number.isNaN(Number(v))) return '-';
  return `${(Number(v) * 100).toFixed(2)}%`;
}

function renderWeekPryDays(_, row) {
  const days = row?.consecutive_days;
  if (!days || days <= 0) return '-';
  if (days === 1) return <Tag>1</Tag>;
  if (days <= 2) return <Tag color="processing">{days}</Tag>;
  if (days <= 4) return <Tag color="warning">{days}</Tag>;
  return <Tag color="error">{days}</Tag>;
}

function PryBoardHistory() {
  const navigate = useNavigate();
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [keyword, setKeyword] = useState('');

  // keyword is passed explicitly by callers; default '' keeps mount fetch stable
  const fetchHistory = useCallback(async (p = 1, kw = '') => {
    setLoading(true);
    try {
      const trimmed = (kw || '').trim();
      const url = `/api/subscribe/pry-board/history?page=${p}&page_size=${PAGE_SIZE}` +
        (trimmed ? `&keyword=${encodeURIComponent(trimmed)}` : '');
      const res = await request(url, { method: 'GET' });
      const rows = res?.data?.list;
      setItems(Array.isArray(rows) ? rows : []);
      setTotal(Number(res?.data?.total) || 0);
      setPage(Number(res?.data?.page) > 0 ? Number(res.data.page) : p);
    } catch (e) {
      message.error(e?.message || '加载历史数据失败');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchHistory(1);
  }, [fetchHistory]);

  const columns = [
    { title: 'ID', dataIndex: 'id', key: 'id', width: 70 },
    { title: '交易日', dataIndex: 'trade_date', key: 'trade_date', width: 110, render: formatDate },
    { title: '代码', dataIndex: 'code', key: 'code', width: 110 },
    { title: '名称', dataIndex: 'name', key: 'name', width: 120, ellipsis: true },
    {
      title: '昨收',
      dataIndex: 'prev_close',
      key: 'prev_close',
      width: 90,
      render: (v) => (v != null ? Number(v).toFixed(2) : '-'),
    },
    {
      title: '跌停价',
      dataIndex: 'limit_down',
      key: 'limit_down',
      width: 90,
      render: (v) => (v != null ? Number(v).toFixed(2) : '-'),
    },
    {
      title: '日内最低',
      dataIndex: 'day_low',
      key: 'day_low',
      width: 90,
      render: (v) => (v != null ? Number(v).toFixed(2) : '-'),
    },
    {
      title: '入库时价',
      dataIndex: 'last_price',
      key: 'last_price',
      width: 90,
      render: (v) => (v != null ? Number(v).toFixed(2) : '-'),
    },
    {
      title: '距高点跌幅',
      dataIndex: 'drop_from_high_pct',
      key: 'drop_from_high_pct',
      width: 100,
      render: (v) => {
        // 首次达标时固化；旧记录未写入时为 0/空
        if (v == null || Number.isNaN(Number(v)) || Number(v) <= 0) return '-';
        return formatPct(v);
      },
    },
    { title: '距跌停', dataIndex: 'near_pct', key: 'near_pct', width: 90, render: formatPct },
    { title: '反弹', dataIndex: 'rebound_pct', key: 'rebound_pct', width: 90, render: formatPct },
    { title: '周内翘板天数', key: 'consecutive_days', width: 110, render: renderWeekPryDays },
    { title: '发现时间', dataIndex: 'detected_at', key: 'detected_at', width: 170, render: formatTime },
    { title: '更新时间', dataIndex: 'updated_at', key: 'updated_at', width: 170, render: formatTime },
  ];

  return (
    <div className="equation-tab-page">
      <div style={{
        position: 'sticky',
        top: 0,
        zIndex: 1000,
        background: '#fff',
        padding: '16px',
        borderBottom: '1px solid #E5E5EA',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
      }}>
        <Button type="text" icon={<ArrowLeftOutlined />} onClick={() => navigate('/pry-board')}>
          返回
        </Button>
        <Space>
          <Input.Search
            placeholder="搜索代码或名称，如 601088"
            allowClear
            value={keyword}
            onChange={(e) => {
              setKeyword(e.target.value);
              if (e.target.value === '') {
                fetchHistory(1, '');
              }
            }}
            onSearch={(v) => fetchHistory(1, v)}
            style={{ width: 240 }}
            enterButton="搜索"
          />
          <Button type="text" icon={<ReloadOutlined />} onClick={() => fetchHistory(page, keyword)} loading={loading}>
            刷新
          </Button>
        </Space>
      </div>

      <Card
        title="撬板历史"
        style={{ margin: '16px', marginTop: 24, borderRadius: 8 }}
        bodyStyle={{ padding: 12, overflowX: 'auto' }}
        extra={<span style={{ color: '#8E8E93', fontSize: 12 }}>按 ID 倒序 · 每页 {PAGE_SIZE} 条</span>}
      >
        <Table
          columns={columns}
          dataSource={items}
          rowKey="id"
          loading={loading}
          size="small"
          scroll={{ x: 'max-content' }}
          locale={{ emptyText: '暂无历史记录' }}
          pagination={{
            current: page,
            pageSize: PAGE_SIZE,
            total,
            showSizeChanger: false,
            showTotal: (n) => `共 ${n} 条`,
            onChange: (p) => fetchHistory(p, keyword),
          }}
        />
      </Card>
    </div>
  );
}

export default PryBoardHistory;
