import React from 'react';
import { HashRouter as Router, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { SafetyOutlined, StarOutlined, DollarOutlined, RocketOutlined, LineChartOutlined } from '@ant-design/icons';
import Login from './pages/Login';
import LowBuyStrategy from './pages/LowBuyStrategy';
import HighSellStrategy from './pages/HighSellStrategy';
import RiskControl from './pages/RiskControl';
import MoreItem from './pages/MoreItem';
import SubscribeStock from './pages/SubscribeStock';
import OptionRate from './pages/OptionRate';
import OptionHistory from './pages/OptionHistory';
import OptionSymbolDetail from './pages/OptionSymbolDetail';
import FundTemperature from './pages/FundTemperature';
import IndicatorBoard from './pages/IndicatorBoard';
import StockPeDebtRatio from './pages/StockPeDebtRatio';
import StockDetectReport from './pages/StockDetectReport';
import FundMarkdownPage from './pages/FundMarkdownPage';
import { HefeiVcCompanyList, HefeiVcCompanyStory } from './pages/HefeiVcCompanies';
import NewStockIssuance from './pages/NewStockIssuance';
import NewStockDetail from './pages/NewStockDetail';
import HoldingChangeDetail from './pages/HoldingChangeDetail';
import MathProofDetail from './pages/MathProofDetail';
import HoldingManagement from './pages/HoldingManagement';
import HkNewStockSupport from './pages/HkNewStockSupport';
import DpBestPathDetail from './pages/DpBestPathDetail';
import PushSignalHistory from './pages/PushSignalHistory';
import PryBoardStocks from './pages/PryBoardStocks';
import PryBoardHistory from './pages/PryBoardHistory';
import BacktestReports from './pages/BacktestReports';
import HighSellReports from './pages/HighSellReports';
import TieredSellStrategy from './pages/TieredSellStrategy';
import OptionBuyerTerm from './pages/OptionBuyerTerm';
import XtxStrategyReport from './pages/XtxStrategyReport';
import InstitutionHoldingsReport from './pages/InstitutionHoldingsReport';
import RedblueReport from './pages/RedblueReport';
import DeepSeekHbmSsdReport from './pages/DeepSeekHbmSsdReport';
import EarningsCalendar from './pages/EarningsCalendar';
import './App.css';
import { message } from 'antd';

// 创建一个包装组件来处理底部导航
const Layout = () => {
  const location = useLocation();
  const [activeKey, setActiveKey] = React.useState('subscribe-stock');

  // 根据当前路径设置活动标签（期权计算器详情仍归属「更多」高亮）
  React.useEffect(() => {
    const path = location.pathname;
    if (path.startsWith('/option-calculator/')) {
      setActiveKey('risk-control');
    } else if (path === '/risk-control') setActiveKey('risk-control');
    else if (path === '/subscribe-stock' || path === '/dp-best-path' || path === '/pry-board' || path === '/pry-board/history' || path === '/tiered-sell') setActiveKey('subscribe-stock');
    else if (path === '/new-stock' || path.startsWith('/new-stock/')) setActiveKey('new-stock');
    else if (path === '/option-rate' || path.startsWith('/option-rate/') || path === '/earnings-calendar') setActiveKey('option-rate');
    else if (path === '/fund-temperature' || path.startsWith('/fund-temperature/') || path === '/push-signal-history') setActiveKey('fund-temperature');
  }, [location]);

  const tabItems = [
    { key: 'subscribe-stock', icon: <StarOutlined />, text: '订阅股票' },
    { key: 'new-stock', icon: <RocketOutlined />, text: '新股发行' },
    { key: 'option-rate', icon: <DollarOutlined />, text: '指标排序' },
    { key: 'fund-temperature', icon: <LineChartOutlined />, text: '观察中心' },
    { key: 'risk-control', icon: <SafetyOutlined />, text: '更多' },
  ];

  const handleTabChange = (key) => {
    const token = localStorage.getItem('token');
    if ((key === 'subscribe-stock' || key === 'new-stock' || key === 'option-rate') && !token) {
      message.error('请先登录');
      setActiveKey('risk-control');
      window.location.hash = '#/login';
      return;
    }
    setActiveKey(key);
    if (key === 'subscribe-stock') window.location.hash = '#/subscribe-stock';
    else if (key === 'new-stock') window.location.hash = '#/new-stock';
    else if (key === 'option-rate') window.location.hash = '#/option-rate';
    else if (key === 'fund-temperature') window.location.hash = '#/fund-temperature';
    else if (key === 'risk-control') window.location.hash = '#/risk-control';
  };

  return (
    <div className="layout">
      <div className="content equation-layout-content" style={{
        width: '100%',
        maxWidth: 'min(1400px, 100%)',
        margin: '0 auto',
        background: '#F2F2F7',
      }}>
        <Routes>
          <Route path="/option-calculator/low-buy" element={<LowBuyStrategy />} />
          <Route path="/option-calculator/high-sell" element={<HighSellStrategy />} />
          <Route path="/low-buy" element={<Navigate to="/option-calculator/low-buy" replace />} />
          <Route path="/high-sell" element={<Navigate to="/option-calculator/high-sell" replace />} />
          <Route path="/subscribe-stock" element={<SubscribeStock />} />
          <Route path="/tiered-sell" element={<TieredSellStrategy />} />
          <Route path="/dp-best-path" element={<DpBestPathDetail />} />
          <Route path="/push-signal-history" element={<PushSignalHistory />} />
          <Route path="/pry-board" element={<PryBoardStocks />} />
          <Route path="/pry-board/history" element={<PryBoardHistory />} />
          <Route path="/backtest-reports" element={<BacktestReports />} />
          <Route path="/high-sell-reports" element={<HighSellReports />} />
          <Route path="/fund-temperature/option-buyer-term" element={<OptionBuyerTerm />} />
          <Route path="/new-stock/support" element={<HkNewStockSupport />} />
          <Route path="/new-stock/:sectionKey" element={<NewStockDetail />} />
          <Route path="/new-stock" element={<NewStockIssuance />} />
          <Route path="/option-rate" element={<OptionRate />} />
          <Route path="/earnings-calendar" element={<EarningsCalendar />} />
          <Route path="/option-rate/history/:symbol" element={<OptionHistory />} />
          <Route path="/option-rate/symbol/:option_symbol" element={<OptionSymbolDetail />} />
          <Route path="/fund-temperature/indicator-board" element={<IndicatorBoard />} />
          <Route path="/fund-temperature/xtx-strategy" element={<XtxStrategyReport />} />
          <Route path="/fund-temperature/institution-holdings" element={<InstitutionHoldingsReport />} />
          <Route path="/fund-temperature/redblue" element={<RedblueReport />} />
          <Route path="/fund-temperature/deepseek-hbm-ssd" element={<DeepSeekHbmSsdReport />} />
          <Route path="/fund-temperature/stock-pe-debt" element={<StockPeDebtRatio />} />
          <Route path="/fund-temperature/stock-detect" element={<StockDetectReport />} />
          <Route path="/fund-temperature/serenity" element={<FundMarkdownPage title="Serenity 投资理论" fileName="fund-temperature-serenity.md" />} />
          <Route path="/fund-temperature/danbin" element={<FundMarkdownPage title="但斌核心指标" fileName="fund-temperature-danbin.md" />} />
          <Route path="/fund-temperature/conquer-market" element={<FundMarkdownPage title="《征服市场的人》观察指标" fileName="fund-temperature-conquer-market.md" />} />
          <Route path="/fund-temperature/optiver" element={<FundMarkdownPage title="Optiver 做市商" fileName="fund-temperature-optiver.md" />} />
          <Route path="/fund-temperature/hefei-vc/:slug" element={<HefeiVcCompanyStory />} />
          <Route path="/fund-temperature/hefei-vc" element={<HefeiVcCompanyList />} />
          <Route path="/fund-temperature" element={<FundTemperature />} />
          <Route path="/risk-control" element={<RiskControl />} />
          <Route path="/holding-change-detail" element={<HoldingChangeDetail />} />
          <Route path="/math-proof" element={<MathProofDetail />} />
          <Route path="/holding-management" element={<HoldingManagement />} />
          <Route path="/more" element={<MoreItem />} />
        </Routes>
      </div>
      <div className="equation-bottom-tabs">
        <div className="equation-bottom-tabs-inner">
          <nav className="equation-bottom-tab-bar" role="tablist" aria-label="主导航">
            {tabItems.map(({ key, icon, text }) => (
              <button
                key={key}
                type="button"
                role="tab"
                aria-selected={activeKey === key}
                className={`equation-bottom-tab-item${activeKey === key ? ' equation-bottom-tab-item--active' : ''}`}
                onClick={() => handleTabChange(key)}
              >
                <span className="equation-tab-icon" aria-hidden="true">{icon}</span>
                <span className="equation-tab-text">{text}</span>
              </button>
            ))}
          </nav>
        </div>
      </div>
    </div>
  );
};

const AppContent = () => {
  return (
    <div className="equation-app-root" style={{
      width: '100%',
      maxWidth: '100%',
      margin: '0 auto',
      boxSizing: 'border-box',
      background: '#F2F2F7',
    }}>
      <Routes>
        <Route path="/login" element={<Login />} />
        <Route path="/" element={<Navigate to="/subscribe-stock" replace />} />
        <Route path="/*" element={<Layout />} />
      </Routes>
    </div>
  );
};

const App = () => {
  return (
    <Router>
      <AppContent />
    </Router>
  );
};

export default App;
