import React, { useCallback, useEffect, useState } from 'react';
import { Card, Table, Select, Input, Switch, Tag, Space, Button, message } from 'antd';
import { ReloadOutlined } from '@ant-design/icons';
import request from '../utils/request';

const { Search } = Input;

const MARKET_OPTIONS = [
  { value: '', label: '全部市场' },
  { value: 'US', label: '🇺🇸 美股' },
  { value: 'HK', label: '🇭🇰 港股' },
  { value: 'JP', label: '🇯🇵 日股' },
  { value: 'CN', label: '🇨🇳 A股' },
];

const RANGE_OPTIONS = [
  { value: 'upcoming', label: '未来 30 天' },
  { value: 'week', label: '未来 7 天' },
  { value: 'recent', label: '近 7 天已发布' },
  { value: 'month', label: '前后 30 天' },
];

const MARKET_TAG = { US: '🇺🇸', HK: '🇭🇰', JP: '🇯🇵', CN: '🇨🇳' };

function formatDate(d) {
  const y = d.getFullYear();
  const m = `${d.getMonth() + 1}`.padStart(2, '0');
  const day = `${d.getDate()}`.padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function buildRange(range) {
  const today = new Date();
  const plus = (n) => {
    const t = new Date(today);
    t.setDate(t.getDate() + n);
    return formatDate(t);
  };
  switch (range) {
    case 'week':
      return { from: formatDate(today), to: plus(7) };
    case 'recent':
      return { from: plus(-7), to: formatDate(today) };
    case 'month':
      return { from: plus(-30), to: plus(30) };
    case 'upcoming':
    default:
      return { from: formatDate(today), to: plus(30) };
  }
}

function EarningsCalendar() {
  const [loading, setLoading] = useState(false);
  const [list, setList] = useState([]);
  const [total, setTotal] = useState(0);
  const [subscribedTotal, setSubscribedTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);
  const [market, setMarket] = useState('');
  const [range, setRange] = useState('upcoming');
  const [keyword, setKeyword] = useState('');
  const [onlySubscribed, setOnlySubscribed] = useState(false);

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const { from, to } = buildRange(range);
      const params = new URLSearchParams({
        page: String(page),
        page_size: String(pageSize),
        from,
        to,
      });
      if (market) params.set('market', market);
      if (keyword) params.set('q', keyword);
      if (onlySubscribed) params.set('only_subscribed', '1');

      const res = await request(`/api/earnings/calendar?${params.toString()}`);
      if (res.code === 200) {
        setList(res.data.list || []);
        setTotal(res.data.total || 0);
        setSubscribedTotal(res.data.subscribed_total || 0);
      } else {
        message.error(res.message || '查询失败');
      }
    } catch (e) {
      message.error('查询失败');
    } finally {
      setLoading(false);
    }
  }, [page, pageSize, market, range, keyword, onlySubscribed]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const columns = [
    {
      title: '财报日',
      dataIndex: 'earnings_date',
      key: 'earnings_date',
      width: 110,
      render: (v, r) => (
        <div>
          <div style={{ fontWeight: 600 }}>{v}</div>
          <div style={{ fontSize: 12, color: '#8E8E93' }}>{r.weekday}</div>
        </div>
      ),
    },
    {
      title: '标的',
      dataIndex: 'stock_name',
      key: 'stock_name',
      width: 170,
      render: (v, r) => (
        <div>
          <div>
            {v || '-'} {MARKET_TAG[r.market] || ''}
            {r.subscribed ? <Tag color="blue" style={{ marginLeft: 6 }}>已关注</Tag> : null}
          </div>
          <div style={{ fontSize: 12, color: '#8E8E93' }}>{r.stock_code}</div>
        </div>
      ),
    },
    {
      title: '预期EPS',
      dataIndex: 'expected_eps',
      key: 'expected_eps',
      width: 100,
      align: 'right',
      render: (v, r) => {
        if (v === null || v === undefined) return <span style={{ color: '#8E8E93' }}>-</span>;
        const symbol = r.price_currency === 'JPY' ? '¥' : r.price_currency === 'HKD' ? 'HK$' : '$';
        return `${symbol}${Number(v).toFixed(2)}`;
      },
    },
    {
      title: '同比',
      dataIndex: 'eps_yoy_change',
      key: 'eps_yoy_change',
      width: 90,
      align: 'right',
      render: (v) => {
        if (v === null || v === undefined) return <span style={{ color: '#8E8E93' }}>-</span>;
        const color = v > 0 ? '#cf1322' : v < 0 ? '#389e0d' : '#8E8E93';
        return (
          <span style={{ fontWeight: 600, color }}>
            {v > 0 ? '+' : ''}{Number(v).toFixed(0)}%
          </span>
        );
      },
    },
    {
      title: '现价',
      dataIndex: 'current_price',
      key: 'current_price',
      width: 100,
      align: 'right',
      render: (v, r) => {
        if (v === null || v === undefined) return <span style={{ color: '#8E8E93' }}>-</span>;
        const symbol = r.price_currency === 'JPY' ? '¥' : r.price_currency === 'HKD' ? 'HK$' : '$';
        return `${symbol}${Number(v).toFixed(2)}`;
      },
    },
  ];

  return (
    <div className="equation-tab-page">
      <Card
        className="equation-table-card"
        title="财报日历"
        style={{ marginBottom: 0, borderRadius: '8px', overflow: 'hidden' }}
        styles={{ body: { padding: '12px' } }}
        extra={
          <Space wrap>
            <Select
              value={range}
              onChange={(v) => { setRange(v); setPage(1); }}
              options={RANGE_OPTIONS}
              style={{ width: 130 }}
            />
            <Select
              value={market}
              onChange={(v) => { setMarket(v); setPage(1); }}
              options={MARKET_OPTIONS}
              style={{ width: 120 }}
            />
            <Search
              placeholder="代码或名称"
              allowClear
              onSearch={(v) => { setKeyword(v.trim()); setPage(1); }}
              style={{ width: 150 }}
            />
            <Space size={4}>
              <span style={{ fontSize: 13 }}>只看已关注</span>
              <Switch
                size="small"
                checked={onlySubscribed}
                onChange={(v) => { setOnlySubscribed(v); setPage(1); }}
              />
            </Space>
            <Button icon={<ReloadOutlined />} onClick={fetchData} />
          </Space>
        }
      >
        <div style={{ marginBottom: 12, fontSize: 13, color: '#8E8E93' }}>
          共 {total} 条（其中已关注 {subscribedTotal} 条）。财报提醒只推送已关注标的，未关注的在这里查询。
        </div>
        <Table
          rowKey={(r) => `${r.stock_code}-${r.earnings_date}`}
          size="small"
          loading={loading}
          columns={columns}
          dataSource={list}
          scroll={{ x: 670 }}
          pagination={{
            current: page,
            pageSize,
            total,
            showSizeChanger: true,
            pageSizeOptions: ['20', '50', '100'],
            onChange: (p, ps) => { setPage(p); setPageSize(ps); },
            showTotal: (t) => `共 ${t} 条`,
          }}
        />
      </Card>
    </div>
  );
}

export default EarningsCalendar;
