/** USDT/USD 现货价接近 1，需比股票更高的展示精度 */
const USDTUSD_SYMBOL = 'USDTUSD';

function formatSubscribeCurrentPrice(value, symbol) {
  const n = Number(value);
  if (!Number.isFinite(n)) {
    return null;
  }
  if (symbol === USDTUSD_SYMBOL) {
    return n.toFixed(4);
  }
  return n.toFixed(2);
}

// 订阅列表「重字段」（P2-7）：列表用 ?view=light 只回轻量字段秒回，随后由 /detail 二次拉取回填这些字段。
const SUBSCRIBE_STOCKS_HEAVY_FIELDS = [
  'l1_trigger_price',
  'recommended_option',
  'call_funding_rate_option',
  'put_funding_rate_option',
  'call_funding_rate_3w_mean',
  'put_funding_rate_3w_mean',
  'week52_median',
  'waist_cut_06_line',
  'tier1_anchor_locked',
  'tier1_anchor_price',
  'tier1_anchor_expiry',
];

/** 把 /detail 返回的重字段合并进列表行（只覆盖重字段，缺失的保留 light 值）。 */
function mergeSubscribeStockDetail(rows, detailMap) {
  if (!detailMap) {
    return rows;
  }
  return rows.map((row) => {
    const detail = row && detailMap[row.symbol];
    if (!detail) {
      return row;
    }
    const merged = { ...row };
    SUBSCRIBE_STOCKS_HEAVY_FIELDS.forEach((key) => {
      if (detail[key] !== undefined) {
        merged[key] = detail[key];
      }
    });
    return merged;
  });
}

/** P2-7：对当前页 symbol 二次拉取重字段；失败/缺参时原样返回 rows（保持轻量展示）。 */
async function fetchSubscribeStocksDetail(rows) {
  const symbols = (rows || []).map((r) => r && r.symbol).filter(Boolean);
  if (symbols.length === 0) {
    return rows;
  }
  try {
    const response = await request(
      `/api/subscribe/stocks/detail?symbols=${encodeURIComponent(symbols.join(','))}`,
      { method: 'GET', silent: true },
    );
    if (!response || response.code !== 200 || !response.data) {
      return rows;
    }
    return mergeSubscribeStockDetail(rows, response.data);
  } catch (error) {
    console.error('加载订阅股票重字段失败:', error);
    return rows;
  }
}

// 监控跌破价格编辑组件（输入框与「已满配/保存」左对齐）
const MonitorDropPriceEditor = ({ record, onSave }) => {
  const [editingPrice, setEditingPrice] = useState(record.monitor_drop_price || 0);
  const [saving, setSaving] = useState(false);
  useEffect(() => {
    setEditingPrice(record.monitor_drop_price || 0);
  }, [record.monitor_drop_price]);

  const handleSave = async () => {
    try {
      setSaving(true);
      const price = parseFloat(editingPrice);
      const requestBody = {
        symbol: record.symbol,
      };
      // 只有当价格存在且大于0时才添加monitor_drop_price字段
      if (price && price > 0) {
        requestBody.monitor_drop_price = price;
      } else {
        // 如果价格为0或空，设置-monitor_drop_price为0（表示清除）
        requestBody.monitor_drop_price = 0;
      }
      const response = await request('/api/subscribe/stocks/monitor-drop-price', {
        method: 'PUT',
        body: JSON.stringify(requestBody),
      });

      if (response.code === 200) {
        message.success('保存监控跌破价格成功');
        if (onSave) {
          onSave();
        }
      } else {
        message.error(response.message || '保存监控跌破价格失败');
      }
    } catch (error) {
      console.error('保存监控跌破价格失败:', error);
      message.error('保存监控跌破价格失败，请稍后重试');
    } finally {
      setSaving(false);
    }
  };

  const handleSetFullPosition = async () => {
    setEditingPrice('0.01');
    try {
      setSaving(true);
      const response = await request('/api/subscribe/stocks/monitor-drop-price', {
        method: 'PUT',
        body: JSON.stringify({
          symbol: record.symbol,
          monitor_drop_price: 0.01,
        }),
      });

      if (response.code === 200) {
        message.success('已设置为满配价 0.01');
        if (onSave) {
          onSave();
        }
      } else {
        message.error(response.message || '设置满配价失败');
      }
    } catch (error) {
      console.error('设置满配价失败:', error);
      message.error('设置满配价失败，请稍后重试');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="subscribe-list-number-input" style={{ display: 'flex', flexDirection: 'column', alignItems: 'stretch', width: '100%' }}>
      <Input
        type="number"
        value={editingPrice || ''}
        onChange={(e) => setEditingPrice(e.target.value)}
        step="0.01"
        min="0"
        style={{ width: '65px', marginBottom: '4px' }}
        onPressEnter={handleSave}
      />
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%' }}>
        <Button
          type="link"
          size="small"
          onClick={handleSetFullPosition}
          loading={saving}
          style={{ padding: 0, margin: 0 }}
        >
          已满配
        </Button>
        <Button
          type="link"
          size="small"
          onClick={handleSave}
          loading={saving}
          style={{ padding: 0, margin: 0 }}
        >
          保存
        </Button>
      </div>
    </div>
  );
};

