import React, { useState, useEffect, useRef } from 'react';
import { Button } from 'antd';
import { ArrowLeftOutlined } from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import { markdownToHtml, applyMathProofHeadingLinkCleanup } from '../utils/markdownToHtml';

function MathProofDetail() {
  const navigate = useNavigate();
  const [content, setContent] = useState('');
  const [loading, setLoading] = useState(true);
  const contentRef = useRef(null);

  useEffect(() => {
    // 读取Markdown文件（从public目录）
    fetch(process.env.PUBLIC_URL + '/期权备兑策略数学论证.md')
      .then(response => {
        if (!response.ok) {
          throw new Error('文件未找到');
        }
        return response.text();
      })
      .then(text => {
        setContent(text);
        setLoading(false);
      })
      .catch(error => {
        console.error('加载文档失败:', error);
        setContent('# 文档加载失败\n\n请稍后重试。如果问题持续，请联系开发者。');
        setLoading(false);
      });
  }, []);

  // 去掉特定标题内链接的下划线
  useEffect(() => {
    if (!loading && contentRef.current) {
      const headings = contentRef.current.querySelectorAll('h1, h2, h3, h4');
      headings.forEach(heading => {
        const text = heading.textContent || heading.innerText || '';
        if (text.includes('策略概述') || 
            text.includes('情景一：指数ETF期权备兑策略') || 
            text.includes('情景二：多只个股期权备兑策略') || 
            text.includes('结论')) {
          // 去掉标题内所有链接的下划线
          const links = heading.querySelectorAll('a');
          links.forEach(link => {
            link.style.textDecoration = 'none';
            link.style.textDecorationLine = 'none';
            link.style.textDecorationStyle = 'none';
          });
          // 也去掉标题本身的任何下划线样式
          heading.style.textDecoration = 'none';
        }
      });
    }
  }, [loading, content]);

  const handleBack = () => {
    navigate(-1);
  };


  return (
    <div style={{ 
      paddingBottom: 'calc(80px + env(safe-area-inset-bottom, 0px) + 50px)',
      minHeight: '100vh',
      boxSizing: 'border-box',
      paddingLeft: 'env(safe-area-inset-left, 0px)',
      paddingRight: 'env(safe-area-inset-right, 0px)',
      paddingTop: 'env(safe-area-inset-top, 0px)',
      WebkitOverflowScrolling: 'touch',
      overflowX: 'hidden',
      width: '100%',
      position: 'relative',
      background: '#fff'
    }}>
      {/* 返回按钮 */}
      <div style={{ 
        position: 'sticky', 
        top: 0, 
        left: 0,
        right: 0,
        zIndex: 1000,
        background: '#fff',
        padding: '16px',
        borderBottom: '1px solid #E5E5EA',
        display: 'flex',
        alignItems: 'center',
        gap: '12px'
      }}>
        <Button
          type="text"
          icon={<ArrowLeftOutlined />}
          onClick={handleBack}
          style={{
            padding: '4px 8px',
            display: 'flex',
            alignItems: 'center',
            gap: '4px'
          }}
        >
          返回
        </Button>
      </div>

      {/* 内容区域 */}
      <div style={{
        maxWidth: '1200px',
        margin: '0 auto',
        padding: '24px 16px'
      }}>
        {loading ? (
          <div style={{ textAlign: 'center', padding: '40px' }}>
            加载中...
          </div>
        ) : (
          <div 
            ref={contentRef}
            style={{
              background: '#fff',
              padding: '24px',
              borderRadius: '8px',
              lineHeight: '1.8',
              fontSize: '16px',
              color: '#1C1C1E',
              border: '1px solid #e8e8e8'
            }}
            dangerouslySetInnerHTML={{ __html: applyMathProofHeadingLinkCleanup(markdownToHtml(content)) }}
          />
        )}
      </div>
    </div>
  );
}

export default MathProofDetail;
