import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Alert, Button, Card, Col, Input, Row, Switch, Table, Tag, message } from 'antd';
import { ArrowLeftOutlined, LockOutlined, ReloadOutlined, SaveOutlined } from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import request from '../utils/request';

// ============================================================
// 分层卖出止盈策略（蓝筹反向策略）
//
// 与「低买策略」（原清算套利，分层买入抄底）互为镜像：
//   低买策略：优先持有现金 → 分层买入 → 反弹止盈（适合高波动成长股）
//   分层卖出：优先持有股票 → 分层卖出 → 回调买回（适合低波动蓝筹）
//
// 设计文档：docs/tiered_sell_strategy.md
// 参数白话对照：docs/分层卖出与清算套利参数对照.md
// 后端接口：/api/risk-control/tiered-sell/{config,summary,trades,status}
//   config → data.items（数组）
//   summary/trades → data（数组）
//   status?symbol= → data（单对象）
// ============================================================

// 持仓管理页标的默认展示中文名；无中文名时才回退到代码。
function formatSymbol(symbol) {
  if (!symbol) return '-';
  const map = {
    'BRK.B': '伯克希尔B',
    'KO': '可口可乐',
    'TLT': '20年期美债ETF',
  };
  return map[symbol] || symbol;
}

function num(v, d = 2) {
  if (v === undefined || v === null || v === '' || Number.isNaN(Number(v))) return '-';
  return Number(v).toFixed(d);
}

function pct(v) {
  if (v === undefined || v === null || v === '' || Number.isNaN(Number(v))) return '-';
  return `${(Number(v) * 100).toFixed(2)}%`;
}

function TieredSellStrategy({ embedded = false } = {}) {
  const navigate = useNavigate();

  const [configLoading, setConfigLoading] = useState(false);
  const [config, setConfig] = useState([]);
  const [drafts, setDrafts] = useState({});
  const [savingMap, setSavingMap] = useState({});

  const [statusLoading, setStatusLoading] = useState(false);
  const [statusMap, setStatusMap] = useState({});
  const [positions, setPositions] = useState([]);
  const [trades, setTrades] = useState([]);

  const isRootUser = useMemo(() => {
    try {
      return localStorage.getItem('username') === 'root';
    } catch (e) {
      return false;
    }
  }, []);

  // ---------- 参数配置 ----------
  const fetchConfig = useCallback(async () => {
    setConfigLoading(true);
    try {
      const res = await request('/api/risk-control/tiered-sell/config', { method: 'GET' });
      // 后端 GET /config 始终返回全部支持标的（未配置的回落默认值），故无需前端兜底占位
      const rows = res?.data?.items || [];
      setConfig(rows);
      const next = {};
      rows.forEach((row) => {
        // 期权张数上限由总持股/底仓推导；草稿保留可编辑项
        next[row.symbol] = {
          initial_shares: row.initial_shares ?? '',
          floor_shares: row.floor_shares ?? '',
          monitor_rise_price: row.monitor_rise_price ? String(row.monitor_rise_price) : '',
        };
      });
      setDrafts(next);
    } catch (e) {
      message.error(e?.message || '读取分层卖出参数失败');
      setConfig([]);
    } finally {
      setConfigLoading(false);
    }
  }, []);

  const fetchStatus = useCallback(async () => {
    setStatusLoading(true);
    try {
      // summary / trades 的 data 直接是数组
      const posRes = await request('/api/risk-control/tiered-sell/summary', { method: 'GET' });
      setPositions(posRes?.data || []);

      const tradeRes = await request('/api/risk-control/tiered-sell/trades', { method: 'GET' });
      setTrades(tradeRes?.data || []);

      // status?symbol= 返回单对象；单标的失败不影响其他标的
      const map = {};
      await Promise.all(config.map(async (row) => {
        const sym = row.symbol;
        try {
          const res = await request(
            `/api/risk-control/tiered-sell/status?symbol=${encodeURIComponent(sym)}`,
            { method: 'GET' },
          );
          if (res?.data) map[sym] = res.data;
        } catch (e) {
          // 行情不可用时后端返回 data_ok=false，此处仅兜网络级异常
        }
      }));
      setStatusMap(map);
    } catch (e) {
      message.error(e?.message || '读取分层卖出持仓失败');
      setPositions([]);
      setTrades([]);
    } finally {
      setStatusLoading(false);
    }
  }, [config]);

  // 一阶触发价记忆：打开 = 已执行本轮一阶卖出，按页面当前展示的 S1 触发价锁定；
  // 关闭 = 解除锁定，下一轮按行情重算。锁定后 S1/S2/S4 都以它为基准（后端已生效）。
  const toggleTier1Anchor = async (symbol, checked, price) => {
    try {
      const resp = checked
        ? await request('/api/risk-control/tiered-sell/tier1-anchor', {
            method: 'POST',
            body: JSON.stringify({ symbol, price: Number(price) || 0, source: 'web' }),
          })
        : await request(
            `/api/risk-control/tiered-sell/tier1-anchor?symbol=${encodeURIComponent(symbol)}`,
            { method: 'DELETE' },
          );
      if (resp && resp.code === 200) {
        if (checked) {
          const anchor = resp.data || {};
          const head = `已锁定一阶触发价 ${num(anchor.tier1_price)}${anchor.call_expiry ? `（期权到期 ${anchor.call_expiry}）` : ''}`;
          // 锁定同时补记 S1 卖 Call 台账；补记失败时说明原因（份额不足/张数上限）
          const ledger = anchor.ledger;
          if (ledger && ledger.recorded) {
            message.success(`${head}；${ledger.message}`, 5);
          } else if (ledger && ledger.deduped) {
            message.info(`${head}；${ledger.message}`, 5);
          } else if (ledger && ledger.message) {
            message.warning(`${head}；${ledger.message}`, 6);
          } else {
            message.success(head);
          }
        } else {
          const note = (resp.data && resp.data.note) || '';
          message.success(note ? `已解除一阶触发价锁定；${note}` : '已解除一阶触发价锁定，下一轮按行情重算', note ? 6 : 3);
        }
        fetchStatus();
      } else {
        message.error((resp && resp.message) || '操作失败');
      }
    } catch (e) {
      console.error('一阶触发价锁定失败:', e);
      message.error('操作失败，请稍后重试');
    }
  };

  useEffect(() => {
    fetchConfig();
  }, [fetchConfig]);

  useEffect(() => {
    if (config.length > 0) fetchStatus();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [config.length]);

  const updateDraft = (symbol, field, value) => {
    setDrafts((prev) => ({
      ...prev,
      [symbol]: { ...(prev[symbol] || {}), [field]: value },
    }));
  };

  const handleSave = async (row) => {
    const draft = drafts[row.symbol] || {};
    const initial = Number(draft.initial_shares);
    const floor = Number(draft.floor_shares);
    const lot = row.lot_size || 100;
    const riseRaw = String(draft.monitor_rise_price ?? '').trim();
    const rise = riseRaw === '' ? 0 : Number(riseRaw);

    // ---- 前端校验（与设计文档 H1/H8 对齐；H11 张数由可卖份额推导）----
    if (!Number.isInteger(initial) || initial <= 0) {
      message.error('总持股数必须为正整数');
      return;
    }
    if (!Number.isInteger(floor) || floor < 0) {
      message.error('底仓股数必须为 ≥ 0 的整数（允许为 0，即允许清空持仓）');
      return;
    }
    if (floor > initial) {
      message.error('底仓股数不能大于总持股数');
      return;
    }
    // H8：可卖份额至少 1 张合约；张数上限 = floor((总持股−底仓)/每手)
    if (initial - floor < lot) {
      message.error(`可卖份额（总持股 ${initial} − 底仓 ${floor} = ${initial - floor}）不足 1 张合约（${lot} 股），S1 无法执行`);
      return;
    }
    if (Number.isNaN(rise) || rise < 0) {
      message.error('止盈卖出阈值须为非负数字（留空表示不设绝对价门槛）');
      return;
    }

    setSavingMap((prev) => ({ ...prev, [row.symbol]: true }));
    try {
      const res = await request('/api/risk-control/tiered-sell/config', {
        method: 'PUT',
        data: {
          symbol: row.symbol,
          initial_shares: initial,
          floor_shares: floor,
          monitor_rise_price: rise,
          enabled: true,
        },
      });
      // 后端成功响应为 code=200（与低买策略一致）
      if (res?.code === 200) {
        message.success('保存分层卖出参数成功');
        fetchConfig();
      } else {
        message.error(res?.message || '保存失败');
      }
    } catch (e) {
      // 后端会回传 H3/H9/H11/H2 等硬约束的具体违规原因，直接展示给用户
      message.error(e?.message || '保存失败');
    } finally {
      setSavingMap((prev) => ({ ...prev, [row.symbol]: false }));
    }
  };

  // ---------- 持仓汇总表 ----------
  const positionColumns = [
    {
      title: '标的',
      dataIndex: 'symbol',
      key: 'symbol',
      render: (v) => formatSymbol(v),
    },
    {
      title: '当前持股',
      dataIndex: 'current_shares',
      key: 'current_shares',
      align: 'right',
      render: (v, row) => (
        <span>
          {v ?? '-'}
          {row.initial_shares ? <span style={{ color: '#999' }}> / {row.initial_shares}</span> : null}
        </span>
      ),
    },
    {
      title: '已卖Call',
      dataIndex: 'sold_call_contracts',
      key: 'sold_call_contracts',
      align: 'right',
      render: (v, row) => (
        <span>
          {v ?? 0} 张
          {row.max_call_contracts ? <span style={{ color: '#999' }}> / {row.max_call_contracts}</span> : null}
        </span>
      ),
    },
    {
      title: '状态',
      dataIndex: 'state',
      key: 'state',
      render: (v) => {
        const colorMap = {
          IDLE: 'default',
          S1_ARMED: 'blue',
          S2_SOLD: 'cyan',
          S4_ALERTED: 'orange',
        };
        return v ? <Tag color={colorMap[v] || 'default'}>{v}</Tag> : '-';
      },
    },
    {
      title: '已实现盈亏',
      dataIndex: 'realized_pnl',
      key: 'realized_pnl',
      align: 'right',
      render: (v) => {
        if (v === undefined || v === null) return '-';
        const n = Number(v);
        return <span style={{ color: n >= 0 ? '#52c41a' : '#ff4d4f' }}>{n.toFixed(2)}</span>;
      },
    },
    {
      title: '循环数',
      dataIndex: 'cycle_count',
      key: 'cycle_count',
      align: 'right',
      render: (v) => v ?? 0,
    },
  ];

  const tradeColumns = [
    { title: '日期', dataIndex: 'date', key: 'date', width: 110 },
    { title: '标的', dataIndex: 'symbol', key: 'symbol', width: 100, render: (v) => v || '-' },
    {
      title: '动作',
      dataIndex: 'action',
      key: 'action',
      width: 130,
      render: (v) => {
        const map = {
          SELL_CALL: { text: 'S1 卖Call', color: 'blue' },
          SELL_SPOT_TIERED: { text: 'S2 卖现货', color: 'orange' },
          BUY_PUT: { text: 'S4 买Put(提示)', color: 'red' },
          BUY_SPOT_BACK: { text: 'B1/B2 买回', color: 'green' },
          ASSIGNMENT_CALL: { text: 'Call行权交货', color: 'purple' },
          EXPIRE_CALL_OTM: { text: 'Call作废', color: 'default' },
        };
        const hit = map[v];
        return hit ? <Tag color={hit.color}>{hit.text}</Tag> : (v || '-');
      },
    },
    { title: '价格', dataIndex: 'price', key: 'price', align: 'right', width: 90, render: (v) => num(v) },
    { title: '数量', dataIndex: 'qty', key: 'qty', align: 'right', width: 80, render: (v) => v ?? '-' },
    { title: '金额', dataIndex: 'amount', key: 'amount', align: 'right', width: 110, render: (v) => num(v) },
    { title: '备注', dataIndex: 'notes', key: 'notes', ellipsis: true },
  ];

  return (
    <div className={embedded ? undefined : 'equation-tab-page'} style={{ paddingBottom: embedded ? 0 : 24 }}>
      {!embedded && (
        <div style={{
          padding: '16px',
          borderBottom: '1px solid #E5E5EA',
          display: 'grid',
          gridTemplateColumns: '1fr auto 1fr',
          alignItems: 'center',
          gap: 8,
        }}>
          <Button
            type="text"
            icon={<ArrowLeftOutlined />}
            onClick={() => navigate('/subscribe-stock')}
            style={{ justifySelf: 'start' }}
          >
            返回
          </Button>
          <span style={{ fontWeight: 600, justifySelf: 'center' }}>分层卖出止盈</span>
          <Button
            type="text"
            icon={<ReloadOutlined />}
            onClick={() => { fetchConfig(); fetchStatus(); }}
            loading={configLoading || statusLoading}
            style={{ justifySelf: 'end' }}
          >
            刷新
          </Button>
        </div>
      )}

      {/* 后端 status 接口会返回行情可用性与 H5 筛选结果，异常时才提示 */}
      {Object.values(statusMap).some((s) => s && s.data_ok === false) && (
        <Alert
          type="warning"
          showIcon
          style={{ margin: '16px', marginBottom: 0 }}
          message="部分标的行情不可用，触发价无法计算"
          description={Object.entries(statusMap)
            .filter(([, s]) => s && s.data_ok === false)
            .map(([sym, s]) => `${sym}：${s.data_note || '未知原因'}`)
            .join('；')}
        />
      )}

      {Object.values(statusMap).some((s) => s && s.data_ok && s.screen_passed === false) && (
        <Alert
          type="warning"
          showIcon
          style={{ margin: '16px', marginBottom: 0 }}
          message="部分标的未通过 H5 波动率筛选"
          description={Object.entries(statusMap)
            .filter(([, s]) => s && s.data_ok && s.screen_passed === false)
            .map(([sym, s]) => `${sym}：${s.screen_reason || ''}`)
            .join('；')}
        />
      )}

      {/* ---------- 交易台账 ---------- */}
      <Card
        title="分层卖出交易记录"
        style={{ margin: '16px', borderRadius: 8 }}
        bodyStyle={{ padding: 12 }}
        loading={statusLoading}
        extra={<Button size="small" onClick={() => fetchStatus()}>刷新</Button>}
      >
        <Table
          dataSource={trades}
          columns={tradeColumns}
          rowKey={(row) => row.id || `${row.date}-${row.action}-${row.symbol}`}
          pagination={{ pageSize: 10, showSizeChanger: false }}
          size="small"
          scroll={{ x: 'max-content' }}
          locale={{ emptyText: '暂无分层卖出交易记录' }}
        />
      </Card>

      {/* ---------- 策略说明 ---------- */}
      <Card
        title="策略说明：与低买策略互为镜像"
        style={{ margin: '16px', marginTop: embedded ? 16 : undefined, borderRadius: 8 }}
        bodyStyle={{ padding: 12 }}
      >
        <Alert
          type="info"
          showIcon
          style={{ marginBottom: 12 }}
          message="优先持有股票，上涨分层卖出，回调买回"
          description={
            <ul style={{ margin: '8px 0 0', paddingLeft: 18 }}>
              <li><strong>低买策略</strong>（分层买入）：优先持<strong>现金</strong> → 下跌分层买入 → 反弹止盈，适合<strong>高波动成长股</strong></li>
              <li><strong>分层卖出</strong>（本策略）：优先持<strong>股票</strong> → 上涨分层卖出 → 回调买回，适合<strong>低波动蓝筹</strong></li>
              <li>执行顺序：<strong>S1 卖 Covered Call → S2 卖现货 →（S3 空层跳过）→ S4 买保护 Put</strong>（严格单向，不可跳级）</li>
              <li>触发距离与买侧对称：事件/S1 行权价 = <strong>两倍波动均值</strong>（2×ATR14）；S2 = S1 行权价 + <strong>一倍</strong>（1×）；S4 = S1 行权价累计 + <strong>四倍</strong>（4×，镜像买侧 L4）；全部不可配置</li>
              <li>⚠️ <strong>S4 买 Put 仅推送 Bark 提示人工操作，系统不自动下单</strong></li>
              <li><strong>S3 为空层</strong>：S2 后自由份额归零，卖 Call/卖现货均会击穿担保，故不设动作</li>
              <li><strong>无熔断机制</strong>：仓位卖光后已无卖出可停，改由 H3 足额担保 + H11 张数上限结构性封死</li>
            </ul>
          }
        />
        <Alert
          type="warning"
          showIcon
          message="风险边界：允许清空持仓，但永不做空"
          description={
            <ul style={{ margin: '8px 0 0', paddingLeft: 18 }}>
              <li>底仓允许设为 <strong>0</strong>（允许被卖光），靠股价回调买回恢复持仓</li>
              <li>但持股数<strong>永不为负</strong>，且 Covered Call 必须<strong>始终足额担保</strong> —— 最坏情况是「持股归零 + 现金在手」</li>
              <li>本策略<strong>无杠杆、无做空</strong>（不镜像低买策略 L3 的双倍做多）</li>
              <li>主要风险是<strong>踏空</strong>：卖出后若单边上涨不回头，机会成本无上限</li>
            </ul>
          }
        />
      </Card>

      {/* ---------- 参数配置 ---------- */}
      <Card
        title="分层卖出参数配置"
        style={{ margin: '16px', marginTop: 0, borderRadius: 8 }}
        bodyStyle={{ padding: 12 }}
        loading={configLoading}
        extra={<Button size="small" onClick={() => fetchConfig()}>刷新</Button>}
      >
        <Alert
          type="info"
          showIcon
          style={{ marginBottom: 16 }}
          message="仓位用绝对股数；可配绝对价门槛；触发距离定死为 ATR14 倍数（1×/2×/4×，与买侧对称）"
          description={
            <ul style={{ margin: '8px 0 0', paddingLeft: 18 }}>
              <li><strong>总持股 / 底仓</strong>：决定能卖多少；期权张数上限 = (总持股 − 底仓) ÷ 每张股数（美股 100），自动推导、须足额备兑</li>
              <li><strong>止盈卖出阈值</strong>：镜像低买策略「套利买入阈值」；现价 ≥ 此价才考虑 S1 开跑（与上涨事件取 max）；留空则仅按两倍波动均值触发</li>
              <li><strong>ATR14</strong>：近 14 个交易日 TR 均值（系统计算，不可改）</li>
              <li><strong>波动尺子</strong>：ATR14 恒定；上涨事件/S1 行权价/S4 Put 行权价/买回距离 = 两倍波动均值；S2 层距 = 一倍；S4 累计距离 = 四倍</li>
              <li>与「持仓管理 → 低买策略」是镜像策略；对照见 <code>docs/分层卖出与清算套利参数对照.md</code></li>
              <li>参数写入策略账户；仅 root 可保存</li>
            </ul>
          }
        />
        {config.map((row) => {
          const draft = drafts[row.symbol] || {};
          const saving = !!savingMap[row.symbol];
          const lot = row.lot_size || 100;
          const initial = Number(draft.initial_shares) || 0;
          const floor = Number(draft.floor_shares) || 0;
          const sellable = Math.max(0, initial - floor);
          const derivedCalls = Math.floor(sellable / lot) || 0;
          return (
            <div
              key={row.symbol}
              style={{ marginBottom: 16, paddingBottom: 12, borderBottom: '1px dashed #e5e5ea' }}
            >
              <div style={{ marginBottom: 8, fontWeight: 600 }}>
                {formatSymbol(row.symbol)}
                <Tag color={row.enabled ? 'green' : 'default'} style={{ marginLeft: 8 }}>
                  {row.enabled ? '已启用' : '未启用'}
                </Tag>
                <span style={{ marginLeft: 8, color: '#999', fontSize: 12 }}>
                  可卖份额 {sellable} {row.qty_unit || '股'}
                  → 期权张数上限 {derivedCalls} 张（自动推导）
                </span>
              </div>
              <Row gutter={[12, 12]}>
                <Col xs={12} sm={6}>
                  <div style={{ marginBottom: 4, color: '#666', fontSize: 13 }}>
                    总持股数（{row.qty_unit || '股'}）
                  </div>
                  <Input
                    type="number"
                    step="1"
                    min="0"
                    placeholder="200"
                    value={draft.initial_shares ?? ''}
                    onChange={(e) => updateDraft(row.symbol, 'initial_shares', e.target.value)}
                  />
                </Col>
                <Col xs={12} sm={6}>
                  <div style={{ marginBottom: 4, color: '#666', fontSize: 13 }}>
                    底仓股数（0 = 允许清空）
                  </div>
                  <Input
                    type="number"
                    step="1"
                    min="0"
                    placeholder="0"
                    value={draft.floor_shares ?? ''}
                    onChange={(e) => updateDraft(row.symbol, 'floor_shares', e.target.value)}
                  />
                </Col>
                <Col xs={12} sm={6}>
                  <div style={{ marginBottom: 4, color: '#666', fontSize: 13 }}>
                    止盈卖出阈值（现价 ≥）
                  </div>
                  <Input
                    type="number"
                    step="0.01"
                    min="0"
                    placeholder="留空则仅按波动触发"
                    value={draft.monitor_rise_price ?? ''}
                    onChange={(e) => updateDraft(row.symbol, 'monitor_rise_price', e.target.value)}
                  />
                </Col>
                <Col xs={12} sm={6}>
                  <div style={{ marginBottom: 4, color: '#666', fontSize: 13 }}>
                    期权张数上限（自动）
                  </div>
                  <div style={{ padding: '5px 0', fontSize: 13, color: '#333' }}>
                    {derivedCalls} 张
                    <span style={{ marginLeft: 6, color: '#999', fontSize: 12 }}>
                      = ({initial || 0} − {floor || 0}) ÷ {lot}
                    </span>
                  </div>
                </Col>
                <Col xs={12} sm={6}>
                  <div style={{ marginBottom: 4, color: '#666', fontSize: 13 }}>
                    波动尺子（只读）
                  </div>
                  <div style={{ padding: '5px 0', fontSize: 13, color: '#333' }}>
                    ATR14 周期 {row.atr_period || 14}；两倍波动均值 = {row.vol_mean_double || 2}×ATR14
                  </div>
                </Col>
                <Col xs={24} sm={6}>
                  <div style={{ marginBottom: 4, fontSize: 13, lineHeight: 1.5715, height: '1.5715em' }} aria-hidden />
                  <Button
                    type="primary"
                    block
                    icon={<SaveOutlined />}
                    loading={saving}
                    disabled={!isRootUser}
                    onClick={() => handleSave(row)}
                  >
                    保存
                  </Button>
                </Col>
              </Row>
            </div>
          );
        })}
        {!configLoading && config.length === 0 && (
          <div style={{ color: '#999' }}>暂无可配置品种</div>
        )}
      </Card>

      {/* ---------- 持仓与策略状态 ---------- */}
      <Card
        title="分层卖出持仓"
        style={{ margin: embedded ? '0 16px' : '16px', marginTop: 0, borderRadius: 8 }}
        bodyStyle={{ padding: 12 }}
        loading={statusLoading}
        extra={<Button size="small" onClick={() => fetchStatus()}>刷新</Button>}
      >
        <Table
          dataSource={positions}
          columns={positionColumns}
          rowKey={(row) => row.symbol}
          pagination={false}
          size="small"
          locale={{ emptyText: '暂无分层卖出持仓（策略未启用）' }}
          style={{ marginBottom: 16 }}
          expandable={{
            expandedRowRender: (row) => {
              const s = statusMap[row.symbol];
              if (!s) {
                return (
                  <span style={{ color: '#999', fontSize: 12, padding: '8px 0', display: 'inline-block' }}>
                    暂无策略状态数据
                  </span>
                );
              }
              const item = (label, value) => (
                <div style={{ display: 'flex', padding: '3px 0', borderBottom: '1px dashed #f0f0f0' }}>
                  <span style={{ flex: '0 0 auto', maxWidth: '45%', color: '#666', fontSize: 12, paddingRight: 8, wordBreak: 'break-all' }}>{label}</span>
                  <span style={{ flex: 1, fontSize: 12, fontFamily: 'monospace', wordBreak: 'break-all', textAlign: 'right' }}>{value}</span>
                </div>
              );
              const layerTag = (label, v) => (
                <Tag color={v ? 'green' : 'default'} style={{ marginRight: 8 }}>
                  {label}{v ? ' ✓' : ' ○'}
                </Tag>
              );
              return (
                <div style={{ padding: '4px 0 8px' }}>
                  {s.next_trigger_formula && (
                    <Alert
                      type="info"
                      showIcon
                      style={{ marginBottom: 12 }}
                      message={`下次触发价：${s.next_trigger_price ? num(s.next_trigger_price) : '—'}（${s.next_layer || '-'}）`}
                      description={s.next_trigger_formula}
                    />
                  )}
                  <Row gutter={[16, 0]}>
                    <Col xs={24} sm={12}>
                      {item('现价 latest_price', num(s.latest_price))}
                      {item('ATR14', s.atr14 ? `${num(s.atr14)}（周期 ${s.atr_period || 14}）` : '-')}
                      {item('两倍波动均值', s.atr14 ? num((s.vol_mean_double || 2) * s.atr14) : '-')}
                      {item('ATR14/价格', s.atr_pct ? pct(s.atr_pct) : '-')}
                      {item('止盈卖出阈值', num(s.monitor_rise_price))}
                      {item('上涨事件触发价', num(s.rally_trigger_price))}
                      {item('S1 触发价', num(s.s1_trigger_price))}
                      {item('S1 Call行权价', num(s.s1_call_strike))}
                      {item('S2 卖出价', num(s.s2_sell_price))}
                    </Col>
                    <Col xs={24} sm={12}>
                      {item('S4 触发价（S1行权价+4×ATR）', num(s.s4_trigger_price))}
                      {item('S4 建议Put行权价', num(s.s4_put_strike))}
                      {item('自由可卖份额', s.free_sellable_shares ?? '-')}
                      {item('买回触发价', num(s.buyback_trigger_price))}
                      {item('底仓股数', s.floor_shares ?? '-')}
                      {item('已卖Call承诺股数', s.sold_call_shares ?? '-')}
                      {item('下一分层', s.next_layer || '-')}
                    </Col>
                  </Row>
                  <div style={{ marginTop: 8, fontSize: 12 }}>
                    <span style={{ color: '#666', marginRight: 8 }}>分层状态：</span>
                    {layerTag('S1', s.s1_triggered)}
                    {layerTag('S2', s.s2_triggered)}
                    <Tag color="default">S3 空层</Tag>
                    {layerTag('S4', s.s4_triggered)}
                  </div>
                  <div style={{ marginTop: 8, fontSize: 12, display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
                    <span style={{ color: '#666' }}>
                      一阶触发价记忆 <LockOutlined style={{ color: s.tier1_anchor_locked ? '#fa8c16' : '#bfbfbf' }} />：
                    </span>
                    <Switch
                      size="small"
                      checked={!!s.tier1_anchor_locked}
                      onChange={(checked) => toggleTier1Anchor(row.symbol, checked, s.s1_trigger_price)}
                    />
                    <span style={{ color: s.tier1_anchor_locked ? '#fa8c16' : '#999' }}>
                      {s.tier1_anchor_locked
                        ? `已锁定 ${num(s.tier1_anchor_price)}，期权到期 ${s.tier1_anchor_expiry || '-'}${
                            s.tier1_anchor_days_left != null ? `（剩 ${s.tier1_anchor_days_left} 天）` : ''
                          }；二/三阶以它为基准，到期自动进入新一轮`
                        : '未锁定：执行一阶卖出后开启，按最近一次 Bark 推送价钉住本轮触发价'}
                    </span>
                  </div>
                </div>
              );
            },
          }}
        />
      </Card>
    </div>
  );
}

export default TieredSellStrategy;
