import React from 'react';

/**
 * DeepSeek HBM / SSD 研究页：嵌入 web/public/deepseek-hbm-ssd-memory.html
 */
function DeepSeekHbmSsdReport() {
  const base = (process.env.PUBLIC_URL || '').replace(/\/$/, '');
  const reportSrc = `${base}/deepseek-hbm-ssd-memory.html`;

  return (
    <iframe
      title="DeepSeek 如何减少对 HBM / SSD 的依赖"
      src={reportSrc}
      style={{
        display: 'block',
        width: '100%',
        minHeight: 'calc(100vh - env(safe-area-inset-top, 0px))',
        height: 'calc(100vh - env(safe-area-inset-top, 0px))',
        border: 'none',
        background: '#F2F2F7',
      }}
    />
  );
}

export default DeepSeekHbmSsdReport;
