import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeftOutlined, FileTextOutlined } from '@ant-design/icons';

/**
 * 机构持仓变更周报：嵌入 web/public/ 下的周报 HTML。
 *
 * 覆盖机构：中财期货 / 贝莱德（BlackRock） / 摩根大通（JPMorgan） / 东方港湾（但斌），
 * 每家机构单独成节，分别汇总近三个月主要持仓变更。
 *
 * 读取 institution-holdings-report-latest.json（由每周 AI 定时任务自动维护），
 * 顶部横向展示历史周报列表（最新在最左），点击切换 iframe 加载对应期数；
 * JSON 不存在时回退到 institution-holdings-report.html（发刊说明页）。
 */
function InstitutionHoldingsReport() {
  const navigate = useNavigate();
  const base = (process.env.PUBLIC_URL || '').replace(/\/$/, '');
  const fallbackSrc = `${base}/institution-holdings-report.html`;
  const [versions, setVersions] = useState([]);
  const [latest, setLatest] = useState('');
  const [current, setCurrent] = useState(fallbackSrc);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    // cache: 'no-store' 避免 Chrome 磁盘缓存旧版 JSON
    fetch(`${base}/institution-holdings-report-latest.json`, { cache: 'no-store' })
      .then((res) => {
        if (!res.ok) throw new Error('not found');
        return res.json();
      })
      .then((data) => {
        if (cancelled || !data.latest) return;
        setLatest(data.latest);
        setVersions(Array.isArray(data.versions) ? data.versions : []);
        const bust = encodeURIComponent(data.updated || data.latest);
        setCurrent(`${base}/${data.latest}?v=${bust}`);
      })
      .catch(() => {
        // JSON 不存在时使用 fallback
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => { cancelled = true; };
  }, [base]);

  const switchVersion = (file, token) => {
    const bust = encodeURIComponent(token || file);
    setCurrent(`${base}/${file}?v=${bust}`);
  };

  if (loading) return null;

  return (
    <div
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        bottom: 'calc(52px + env(safe-area-inset-bottom, 0px))',
        display: 'flex',
        flexDirection: 'column',
        background: '#f5f6f8',
        zIndex: 10,
      }}
    >
      <div
        style={{
          flex: 'none',
          display: 'flex',
          alignItems: 'center',
          gap: 10,
          paddingTop: 'calc(8px + env(safe-area-inset-top, 0px))',
          paddingBottom: 8,
          paddingLeft: 'calc(12px + env(safe-area-inset-left, 0px))',
          paddingRight: 'calc(12px + env(safe-area-inset-right, 0px))',
          background: 'rgba(255, 255, 255, 0.92)',
          borderBottom: '0.5px solid rgba(0, 0, 0, 0.08)',
        }}
      >
        <button
          type="button"
          onClick={() => navigate('/fund-temperature')}
          style={{
            display: 'inline-flex',
            alignItems: 'center',
            gap: 5,
            border: 'none',
            background: 'rgba(0, 122, 255, 0.08)',
            fontSize: 15,
            fontWeight: 500,
            color: '#007AFF',
            cursor: 'pointer',
            padding: '8px 14px',
            borderRadius: 980,
            WebkitTapHighlightColor: 'transparent',
            minHeight: 36,
          }}
        >
          <ArrowLeftOutlined style={{ fontSize: 14 }} />
          返回
        </button>
        <span style={{ fontSize: 16, fontWeight: 600, color: '#1C1C1E' }}>
          机构持仓变更周报
        </span>
      </div>
      {versions.length > 0 && (
        <div
          style={{
            flex: 'none',
            display: 'flex',
            gap: 8,
            overflowX: 'auto',
            padding: '10px 12px',
            background: '#fff',
            borderBottom: '0.5px solid rgba(0, 0, 0, 0.08)',
            WebkitOverflowScrolling: 'touch',
          }}
        >
          {versions.map((v) => {
            const file = v.file || v.latest;
            if (!file) return null;
            const isActive = latest && file === latest;
            return (
              <button
                key={file}
                type="button"
                onClick={() => switchVersion(file, v.date)}
                style={{
                  flex: 'none',
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: 5,
                  border: '1px solid',
                  borderColor: current.startsWith(`${base}/${file}?`)
                    ? '#007AFF'
                    : 'rgba(0, 0, 0, 0.12)',
                  background: current.startsWith(`${base}/${file}?`)
                    ? 'rgba(0, 122, 255, 0.08)'
                    : '#fff',
                  color: current.startsWith(`${base}/${file}?`) ? '#007AFF' : '#3C3C43',
                  fontSize: 13,
                  fontWeight: 500,
                  cursor: 'pointer',
                  padding: '6px 12px',
                  borderRadius: 980,
                  WebkitTapHighlightColor: 'transparent',
                  whiteSpace: 'nowrap',
                }}
              >
                <FileTextOutlined style={{ fontSize: 12 }} />
                {v.date || file}
                {isActive ? ' · 最新' : ''}
              </button>
            );
          })}
        </div>
      )}
      <iframe
        title="机构持仓变更周报（中财期货 / 贝莱德 / 摩根大通 / 东方港湾）"
        src={current}
        style={{
          flex: 1,
          display: 'block',
          width: '100%',
          border: 'none',
          background: '#f5f6f8',
          minHeight: 0,
        }}
      />
    </div>
  );
}

export default InstitutionHoldingsReport;
