import { message } from 'antd';

// 创建请求拦截器
const request = async (url, options = {}) => {
  // silent: 可选调用方（如订阅列表二次拉取重字段）自行静默降级，不弹全局错误提示
  const silent = options.silent === true;
  // 获取token
  const token = localStorage.getItem('token');
  
  // 获取当前路径
  const currentPath = window.location.hash;
  
  // 不需要登录的页面路径
  const publicPaths = ['#/option-calculator/low-buy', '#/more', '#/risk-control', '#/fund-temperature', '#/fund-temperature/indicator-board', '#/fund-temperature/stock-detect', '#/fund-temperature/hefei-vc', '#/fund-temperature/optiver'];
  const publicPathPrefixes = ['#/fund-temperature/hefei-vc/'];
  const publicApiPaths = ['/api/fund-temperature/indicator-board', '/api/stock-detect/report', '/api/stock-detect/manifest', '/api/stock-detect/accounts', '/api/stock-detect/batches', '/api/new-stock/cbond-first-day-updates', '/api/new-stock/cbond-upcoming-calendar'];
  const isPublicApi = publicApiPaths.some((p) => url.includes(p));
  const isPublicPath =
    publicPaths.includes(currentPath) ||
    publicPathPrefixes.some((p) => currentPath.startsWith(p));

  // 如果不是登录请求且没有token，且不在公开页面中，则跳转到登录页
  const isAuthBootstrap =
    url.includes('/api/auth/login') || url.includes('/api/auth/agent-test/mint');
  if (!isAuthBootstrap && !isPublicApi && !token && !isPublicPath) {
    message.error('请先登录');
    window.location.hash = '#/login';
    return;
  }

  // 设置默认headers
  const defaultHeaders = {
    'Content-Type': 'application/json',
    'Cache-Control': 'no-cache, no-store, must-revalidate',
    'Pragma': 'no-cache',
    'Expires': '0'
  };

  // 如果有token，添加到headers
  if (token) {
    defaultHeaders['Authorization'] = `Bearer ${token}`;
  }

  // 合并headers
  const headers = {
    ...defaultHeaders,
    ...options.headers,
  };

  // 根据当前域名自动判断API服务器地址
  const getBaseURL = () => {
    const hostname = window.location.hostname;
    // 本地开发环境
    if (hostname === 'localhost' || hostname === '127.0.0.1' || hostname === '') {
      return 'http://localhost:64480';
    }
    // 生产环境
    return 'https://quadraticequation.top';
  };

  const baseURL = getBaseURL();

  try {
    console.log('Making request to:', `${baseURL}${url}`);
    console.log('Request headers:', headers);

    // 单次请求；失败由用户手动刷新页面重试，前端不做自动重试。
    const response = await fetch(`${baseURL}${url}`, {
      ...options,
      headers,
      mode: 'cors',  // 保持 CORS 支持
      credentials: 'omit',  // 改回 omit，因为我们不需要发送 cookies
      cache: 'no-store'  // 禁用浏览器缓存
    });

    // 检查HTTP状态码
    if (!response.ok) {
      if (response.status === 401) {
        // 清除token
        localStorage.removeItem('token');
        // 显示错误信息
        message.error('登录已过期，请重新登录');
        // 跳转到登录页
        window.location.hash = '#/login';
        return;
      }
      // 对常见网关/服务端错误给出明确文案，避免用户看到模糊的 HTTP error 或 Failed to fetch。
      const gatewayReasonMap = {
        408: '请求超时（408），请稍后刷新页面重试',
        429: '请求过于频繁（429），请稍后再试',
        500: '服务端异常（500），请稍后刷新页面重试',
        502: '网关错误（502），请稍后刷新页面重试',
        503: '服务暂不可用（503），请稍后刷新页面重试',
        504: '后端处理超时（504），请稍后刷新页面重试',
      };
      if (gatewayReasonMap[response.status]) {
        if (!silent) {
          message.error(gatewayReasonMap[response.status]);
        }
        return;
      }
      // 其它非 2xx：优先展示后端 JSON 里的 message，解析失败时回退到通用文案。
      let backendMessage = '';
      try {
        const errorData = await response.json();
        backendMessage = errorData && errorData.message;
      } catch (_) {
        // 后端未返回 JSON（例如上游截断），忽略
      }
      throw new Error(backendMessage || `请求失败（HTTP ${response.status}），请稍后刷新页面重试`);
    }

    const data = await response.json();
    console.log('Response data:', data);

    // 如果返回401，说明token过期或无效
    if (data.code === 401) {
      // 清除token
      localStorage.removeItem('token');
      // 显示错误信息
      message.error('登录已过期，请重新登录');
      // 跳转到登录页
      window.location.hash = '#/login';
      return;
    }

    // 如果返回的不是成功状态码或状态不是success，显示错误信息
    if (data.code !== 200 && data.status !== "success") {
      if (!silent) {
        message.error(data.message || '请求失败');
      }
      return;
    }

    return data;
  } catch (error) {
    console.error('Request failed:', error);
    if (!silent) {
      message.error(error.message || '请求失败，请稍后重试');
    }
    throw error;
  }
};

export default request; 
