import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeftOutlined } from '@ant-design/icons';
import { markdownToHtml } from '../utils/markdownToHtml';

function FundMarkdownPage({ title, fileName, backTo = '/fund-temperature' }) {
  const navigate = useNavigate();
  const [content, setContent] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const markdownUrl = `${process.env.PUBLIC_URL}/${fileName}?t=${Date.now()}`;
    fetch(markdownUrl, { cache: 'no-store' })
      .then((response) => {
        if (!response.ok) throw new Error('文件未找到');
        return response.text();
      })
      .then((text) => {
        // 相对路径图片补上 PUBLIC_URL，便于 public/ 下静态资源在 /equation 部署可用
        const base = (process.env.PUBLIC_URL || '').replace(/\/$/, '');
        const resolved = text.replace(
          /!\[([^\]]*)\]\((?!https?:|\/|data:)([^)]+)\)/g,
          (_, alt, src) => `![${alt}](${base}/${src.replace(/^\.\//, '')})`
        );
        setContent(resolved);
        setLoading(false);
      })
      .catch(() => {
        setContent('# 文档加载失败\n\n请稍后重试。');
        setLoading(false);
      });
  }, [fileName]);

  return (
    <div className="equation-fund-temperature-page equation-tab-page" style={{ background: '#F2F2F7' }}>
      <div
        className="equation-page-inner"
        style={{
          maxWidth: '1200px',
          margin: '0 auto',
          padding: '20px 16px',
        }}
      >
        <div
          className="equation-page-header"
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 12,
            marginBottom: 16,
          }}
        >
          <ArrowLeftOutlined
            style={{ fontSize: 20, color: '#1C1C1E', cursor: 'pointer' }}
            onClick={() => navigate(backTo)}
          />
          <span style={{ fontSize: 22, fontWeight: 700, color: '#1C1C1E' }}>{title}</span>
        </div>
        {loading ? (
          <div style={{ textAlign: 'center', padding: '40px' }}>加载中...</div>
        ) : (
          <div
            className="equation-markdown-panel"
            style={{
              background: '#fff',
              padding: '24px',
              borderRadius: '14px',
              lineHeight: '1.8',
              fontSize: '16px',
              color: '#1C1C1E',
              boxShadow: '0 2px 8px rgba(0,0,0,0.06)',
              overflowX: 'auto',
            }}
            dangerouslySetInnerHTML={{ __html: markdownToHtml(content) }}
          />
        )}
      </div>
    </div>
  );
}

export default FundMarkdownPage;
