import React, { useState, useEffect } from 'react';
import { Card, Descriptions, Tag, Spin, Empty, DatePicker, Space } from 'antd';
import { useParams, useNavigate } from 'react-router-dom';
import dayjs from 'dayjs';
import request from '../utils/request';
import KLineChart from '../components/KLineChart';

// 走势图默认展示最近两周
const DEFAULT_CHART_DAYS = 14;

const formatDate = (d) => {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
};

function OptionSymbolDetail() {
  const { option_symbol } = useParams();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [detail, setDetail] = useState(null);
  const [klines, setKlines] = useState([]);
  // 结束时间固定为今天（只显示，不可切换）；开始时间可由用户选择，默认两周前
  const endDate = formatDate(new Date());
  const [startDate, setStartDate] = useState(() => {
    const d = new Date();
    d.setDate(d.getDate() - DEFAULT_CHART_DAYS);
    return formatDate(d);
  });

  useEffect(() => {
    if (!option_symbol) return;

    let cancelled = false;
    setDetail(null);
    setLoading(true);

    const encoded = encodeURIComponent(option_symbol);
    request(`/api/option-rate/detail/${encoded}`)
      .then((res) => {
        if (cancelled) return;
        if (res?.code === 200 && res.data) setDetail(res.data);
      })
      .catch((error) => {
        if (!cancelled) console.error('加载期权详情失败:', error);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => { cancelled = true; };
  }, [option_symbol]);

  // 走势图数据：合约或起始日期变化时重新拉取（结束日期固定为今天）
  useEffect(() => {
    if (!option_symbol) return;

    let cancelled = false;
    // 切换合约时先清空，避免短暂显示上一合约图表数据
    setKlines([]);

    const encoded = encodeURIComponent(option_symbol);
    request(`/api/option-rate/kline/${encoded}?start_date=${startDate}&end_date=${endDate}`)
      .then((res) => {
        if (cancelled) return;
        if (res?.code === 200 && res.data) setKlines(res.data.klines || []);
      })
      .catch((error) => {
        if (!cancelled) console.error('加载模拟成交价走势失败:', error);
      });

    return () => { cancelled = true; };
  }, [option_symbol, startDate, endDate]);

  if (loading) return <Spin spinning={true} style={{ display: 'block', marginTop: 60 }} />;
  if (!detail) return <Empty description="暂无数据" />;

  return (
    <div className="equation-tab-page">
      <Card
        className="equation-table-card"
        title={
          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
            <span onClick={() => navigate(-1)} style={{ cursor: 'pointer', color: '#1677ff' }}>← 返回</span>
            <span>{option_symbol} 期权详情</span>
          </div>
        }
        style={{ marginBottom: 24, borderRadius: '8px', overflow: 'hidden' }}
        styles={{ body: { padding: '16px' } }}
      >
        <Descriptions column={3} size="small" bordered>
          <Descriptions.Item label="标的代码">{detail.symbol}</Descriptions.Item>
          <Descriptions.Item label="期权代码">{detail.option_symbol}</Descriptions.Item>
          <Descriptions.Item label="行权价">${detail.strike_price?.toFixed(2)}</Descriptions.Item>
          <Descriptions.Item label="到期日">{detail.expiry_date}</Descriptions.Item>
          <Descriptions.Item label="期权类型">
            <Tag color={detail.put_call === 'CALL' ? 'green' : 'red'}>
              {detail.put_call === 'CALL' ? '看涨' : '看跌'}
            </Tag>
          </Descriptions.Item>
          <Descriptions.Item label="最新价">${detail.latest_price?.toFixed(2)}</Descriptions.Item>
          <Descriptions.Item label="买价">${detail.bid_price?.toFixed(2)}</Descriptions.Item>
          <Descriptions.Item label="卖价">${detail.ask_price?.toFixed(2)}</Descriptions.Item>
          <Descriptions.Item label="模拟成交价">${detail.sim_fill_price?.toFixed(2)}</Descriptions.Item>
          <Descriptions.Item label="持仓量">{detail.open_interest?.toLocaleString()}</Descriptions.Item>
          <Descriptions.Item label="标的现价">${detail.underlying_price?.toFixed(2)}</Descriptions.Item>
          <Descriptions.Item label="市场">{detail.market}</Descriptions.Item>
          <Descriptions.Item label="中文名称">{detail.chinese_name}</Descriptions.Item>
          <Descriptions.Item label="英文名称">{detail.english_name}</Descriptions.Item>
          <Descriptions.Item label="快照时间">{detail.create_at}</Descriptions.Item>
        </Descriptions>
      </Card>

      <Card
        className="equation-table-card"
        title="模拟成交价走势（每日早/午快照横线 + 折线）"
        style={{ borderRadius: '8px', overflow: 'hidden' }}
        styles={{ body: { padding: '16px' } }}
        extra={
          <Space size={6} wrap>
            <span style={{ color: '#666', fontSize: 12 }}>起始日期:</span>
            <DatePicker
              value={dayjs(startDate)}
              onChange={(date) => {
                if (date && date.format) setStartDate(date.format('YYYY-MM-DD'));
              }}
              disabledDate={(current) => current && current.isAfter(dayjs(endDate), 'day')}
              format="YYYY-MM-DD"
              allowClear={false}
              size="small"
            />
            <span style={{ color: '#8E8E93', fontSize: 12 }}>~ {endDate}（至今）</span>
          </Space>
        }
      >
        <KLineChart key={option_symbol} data={klines} width={760} height={360} />
        {klines.length === 0 && (
          <div style={{ textAlign: 'center', padding: 20, color: '#999' }}>
            暂无快照数据（需要定时任务抓取多个快照后才有数据）
          </div>
        )}
      </Card>
    </div>
  );
}

export default OptionSymbolDetail;
