import React, { useEffect, useState, useCallback } from 'react';
import { Card, Row, Col, Spin, Empty, Tag, Button, Typography, message } from 'antd';
import { ArrowLeftOutlined, ReloadOutlined, FileTextOutlined } from '@ant-design/icons';

const { Title, Text } = Typography;

function apiBase() {
  const h = window.location.hostname;
  if (h === 'localhost' || h === '127.0.0.1' || h === '') {
    return 'http://localhost:64480';
  }
  return 'https://quadraticequation.top';
}

function BacktestReports() {
  const [loading, setLoading] = useState(true);
  const [reports, setReports] = useState([]);
  const [updatedAt, setUpdatedAt] = useState('');

  const loadReports = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetch(`${apiBase()}/equation/backtest-reports/manifest.json`, { cache: 'no-store' });
      if (!res.ok) {
        throw new Error(`HTTP ${res.status}`);
      }
      const data = await res.json();
      setReports(data.reports || []);
      setUpdatedAt(data.updated_at || '');
    } catch (err) {
      console.error('加载复盘报告列表失败:', err);
      message.error('加载复盘报告列表失败');
      setReports([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadReports();
  }, [loadReports]);

  const handleBack = () => {
    window.location.hash = '#/risk-control';
  };

  const handleOpenReport = (url) => {
    window.open(url, '_blank', 'noopener,noreferrer');
  };

  return (
    <div className="equation-page-inner" style={{ padding: '24px 16px' }}>
      <div style={{
        position: 'absolute',
        top: '16px',
        left: '16px',
        right: '16px',
        zIndex: 1000,
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center'
      }}>
        <Button
          type="text"
          icon={<ArrowLeftOutlined />}
          onClick={handleBack}
          style={{ padding: '4px 8px', display: 'flex', alignItems: 'center', gap: '4px' }}
        >
          返回
        </Button>
        <Button
          type="text"
          icon={<ReloadOutlined />}
          onClick={loadReports}
          style={{ padding: '4px 8px' }}
        >
          刷新
        </Button>
      </div>

      <div style={{ marginTop: 48, marginBottom: 16 }}>
        <Title level={4} style={{ marginBottom: 4 }}>套利事件复盘报告</Title>
        <Text type="secondary" style={{ fontSize: 13 }}>
          每月1-14号自动选取订阅股票进行低买策略事件回测
          {updatedAt && ` · 最近更新: ${updatedAt}`}
        </Text>
      </div>

      {loading ? (
        <div style={{ textAlign: 'center', padding: '60px 0' }}>
          <Spin size="large" />
        </div>
      ) : reports.length === 0 ? (
        <Empty description="暂无复盘报告" />
      ) : (
        <Row gutter={[12, 12]}>
          {reports.map((report, index) => (
            <Col xs={24} sm={12} md={8} lg={6} key={index}>
              <Card
                size="small"
                hoverable
                onClick={() => handleOpenReport(report.url)}
                style={{ borderRadius: '8px', transition: 'all 0.3s' }}
                styles={{ body: { padding: '14px 16px' } }}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4 }}>
                      <FileTextOutlined style={{ color: '#1890ff' }} />
                      <Text strong style={{ fontSize: 15 }}>{report.symbol}</Text>
                    </div>
                    <Text type="secondary" style={{ fontSize: 12 }}>{report.date}</Text>
                  </div>
                  <Tag color="blue">查看</Tag>
                </div>
              </Card>
            </Col>
          ))}
        </Row>
      )}
    </div>
  );
}

export default BacktestReports;
