import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Button,
  Card,
  Col,
  Empty,
  Row,
  Segmented,
  Select,
  Space,
  Spin,
  Table,
  Tag,
  Typography,
} from 'antd';
import { ArrowLeftOutlined, ReloadOutlined } from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';

const { Title, Text } = Typography;

const SCOPE_WINDOW = 'window';
const SCOPE_BATCH = 'batch';

const CONSENSUS_TAG = {
  buy: { color: 'success', label: '买入' },
  sell: { color: 'error', label: '卖出' },
  hold: { color: 'warning', label: '持有' },
  neutral: { color: 'default', label: '中性' },
};

function apiBase() {
  const h = window.location.hostname;
  if (h === 'localhost' || h === '127.0.0.1' || h === '') {
    return 'http://localhost:64480';
  }
  return 'https://quadraticequation.top';
}

async function stockDetectFetch(path) {
  const res = await fetch(`${apiBase()}${path}`, { cache: 'no-store' });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    throw new Error(data.message || `HTTP ${res.status}`);
  }
  return data;
}

function fmtTime(iso) {
  if (!iso) return '—';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleString('zh-CN', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  });
}

function StatCard({ label, value, hint }) {
  return (
    <Card size="small" styles={{ body: { padding: '14px 16px' } }}>
      <div style={{ fontSize: 24, fontWeight: 700, color: '#1C1C1E', letterSpacing: '-0.02em' }}>{value}</div>
      <div style={{ fontSize: 13, color: '#8E8E93', marginTop: 4 }}>{label}</div>
      {hint ? (
        <div style={{ fontSize: 11, color: '#AEAEB2', marginTop: 2 }}>{hint}</div>
      ) : null}
    </Card>
  );
}

function cacheSpanDays(oldestIso, newestIso) {
  if (!oldestIso || !newestIso) return null;
  const start = new Date(oldestIso);
  const end = new Date(newestIso);
  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || end <= start) return null;
  return Math.max(1, Math.ceil((end - start) / (24 * 60 * 60 * 1000)));
}

function StockDetectReport() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [accounts, setAccounts] = useState([]);
  const [batches, setBatches] = useState([]);
  const [report, setReport] = useState(null);
  const [account, setAccount] = useState('aleabitoreddit');
  const [scope, setScope] = useState(SCOPE_WINDOW);
  const [batchAt, setBatchAt] = useState(null);
  const [error, setError] = useState('');

  const selectedAccountMeta = useMemo(
    () => accounts.find((a) => a.account === account),
    [accounts, account],
  );

  const loadAccounts = useCallback(async () => {
    const data = await stockDetectFetch('/api/stock-detect/accounts');
    return Array.isArray(data.accounts) ? data.accounts : [];
  }, []);

  const loadBatches = useCallback(async (acct) => {
    const data = await stockDetectFetch(`/api/stock-detect/batches?account=${encodeURIComponent(acct)}&limit=40`);
    return Array.isArray(data.batches) ? data.batches : [];
  }, []);

  const cacheDays = useMemo(
    () => cacheSpanDays(selectedAccountMeta?.oldest_post_at, selectedAccountMeta?.newest_post_at),
    [selectedAccountMeta],
  );

  const loadReport = useCallback(async (acct, reportScope, batchFetchedAt) => {
    const params = new URLSearchParams({
      account: acct,
      scope: reportScope,
      window_days: '0',
    });
    if (reportScope === SCOPE_BATCH && batchFetchedAt) {
      params.set('batch_fetched_at', batchFetchedAt);
    }
    return stockDetectFetch(`/api/stock-detect/report?${params.toString()}`);
  }, []);

  const refresh = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const list = await loadAccounts();
      setAccounts(list);
      const acct = list.some((a) => a.account === account) ? account : (list[0]?.account || account);
      if (acct !== account) {
        setAccount(acct);
        return;
      }

      const batchList = await loadBatches(acct);
      setBatches(batchList);

      if (scope === SCOPE_BATCH && !batchAt && batchList.length) {
        setBatchAt(batchList[0].fetched_at);
        return;
      }

      const rep = await loadReport(acct, scope, scope === SCOPE_BATCH ? batchAt : null);
      setReport(rep);
    } catch (e) {
      setError(e.message || '加载失败');
      setReport(null);
    } finally {
      setLoading(false);
    }
  }, [account, scope, batchAt, loadAccounts, loadBatches, loadReport]);

  useEffect(() => {
    refresh();
  }, [account, scope, batchAt, refresh]);

  const onScopeChange = (val) => {
    setScope(val);
    if (val === SCOPE_BATCH && batches.length && !batchAt) {
      setBatchAt(batches[0].fetched_at);
    }
  };

  const onAccountChange = (val) => {
    setAccount(val);
    setBatchAt(null);
  };

  const columns = [
    {
      title: '标的',
      dataIndex: 'ticker',
      key: 'ticker',
      render: (t) => <Text strong>${t}</Text>,
    },
    {
      title: '提及',
      dataIndex: 'mentions',
      key: 'mentions',
      width: 72,
    },
    {
      title: '买入',
      dataIndex: 'buy',
      key: 'buy',
      width: 72,
      sorter: (a, b) => (a.buy || 0) - (b.buy || 0),
      defaultSortOrder: 'descend',
      render: (v) => (v > 0 ? <Text style={{ color: '#34C759' }}>{v}</Text> : v),
    },
    {
      title: '卖出',
      dataIndex: 'sell',
      key: 'sell',
      width: 72,
      render: (v) => (v > 0 ? <Text style={{ color: '#FF3B30' }}>{v}</Text> : '—'),
    },
    {
      title: '共识',
      dataIndex: 'consensus',
      key: 'consensus',
      width: 88,
      render: (c) => {
        const meta = CONSENSUS_TAG[c] || CONSENSUS_TAG.neutral;
        return <Tag color={meta.color}>{meta.label}</Tag>;
      },
    },
  ];

  const buyChips = (report?.buy_consensus || []).slice(0, 24);

  return (
    <div className="equation-tab-page" style={{ background: '#F2F2F7', minHeight: '100%' }}>
      <div style={{ maxWidth: 1200, margin: '0 auto', padding: '16px' }}>
        <Space direction="vertical" size="middle" style={{ width: '100%' }}>
          <Row align="middle" justify="space-between" wrap={false} gutter={8}>
            <Col flex="none">
              <Button type="text" icon={<ArrowLeftOutlined />} onClick={() => navigate('/fund-temperature')}>
                返回
              </Button>
            </Col>
            <Col flex="auto" style={{ textAlign: 'center' }}>
              <Title level={4} style={{ margin: 0, fontSize: 20, fontWeight: 700, color: '#1C1C1E' }}>
                X 舆情分析
              </Title>
            </Col>
            <Col flex="none">
              <Button type="link" icon={<ReloadOutlined />} onClick={refresh} disabled={loading}>
                刷新
              </Button>
            </Col>
          </Row>

          <Card size="small" styles={{ body: { padding: 16 } }}>
            <Space direction="vertical" size="middle" style={{ width: '100%' }}>
              <Row gutter={[12, 12]} align="middle">
                <Col xs={24} md={10}>
                  <Text type="secondary" style={{ fontSize: 12, display: 'block', marginBottom: 6 }}>
                    博主
                  </Text>
                  <Select
                    style={{ width: '100%' }}
                    value={account}
                    onChange={onAccountChange}
                    options={accounts.map((a) => ({
                      value: a.account,
                      label: `${a.display_name || `@${a.account}`}（${a.post_count} 帖）`,
                    }))}
                    showSearch
                    optionFilterProp="label"
                    placeholder="选择博主"
                  />
                </Col>
                <Col xs={24} md={14}>
                  <Text type="secondary" style={{ fontSize: 12, display: 'block', marginBottom: 6 }}>
                    分析范围
                  </Text>
                  <Segmented
                    block
                    value={scope}
                    onChange={onScopeChange}
                    options={[
                      {
                        label: cacheDays ? `全量缓存（约 ${cacheDays} 天）` : '全量缓存',
                        value: SCOPE_WINDOW,
                      },
                      { label: '本批次入库', value: SCOPE_BATCH },
                    ]}
                  />
                </Col>
              </Row>

              {selectedAccountMeta ? (
                <Text type="secondary" style={{ fontSize: 12 }}>
                  缓存 {selectedAccountMeta.post_count} 帖
                  {selectedAccountMeta.oldest_post_at && selectedAccountMeta.newest_post_at
                    ? ` · 发帖跨度 ${fmtTime(selectedAccountMeta.oldest_post_at).slice(0, 10)} ~ ${fmtTime(selectedAccountMeta.newest_post_at).slice(0, 10)}`
                    : ''}
                  {selectedAccountMeta.last_fetched_at ? ` · 最近入库 ${fmtTime(selectedAccountMeta.last_fetched_at)}` : ''}
                  {selectedAccountMeta.last_fetch_at ? ` · CI 拉取 ${fmtTime(selectedAccountMeta.last_fetch_at)}` : ''}
                </Text>
              ) : null}
            </Space>
          </Card>

          {scope === SCOPE_BATCH ? (
            <Card size="small" title="入库批次" styles={{ body: { padding: 12 } }}>
              {batches.length === 0 && !loading ? (
                <Empty description="暂无批次数据" image={Empty.PRESENTED_IMAGE_SIMPLE} />
              ) : (
                <div style={{ display: 'flex', gap: 8, overflowX: 'auto', paddingBottom: 4 }}>
                  {batches.map((b) => {
                    const key = b.fetched_at;
                    const selected = batchAt === key;
                    return (
                      <Card
                        key={key}
                        size="small"
                        hoverable
                        onClick={() => setBatchAt(key)}
                        style={{
                          minWidth: 168,
                          flex: '0 0 auto',
                          borderColor: selected ? '#007AFF' : '#E5E5EA',
                          background: selected ? 'rgba(0,122,255,0.06)' : '#fff',
                          cursor: 'pointer',
                        }}
                        styles={{ body: { padding: '10px 12px' } }}
                      >
                        <div style={{ fontSize: 13, fontWeight: 600, color: '#1C1C1E' }}>
                          {fmtTime(b.fetched_at)}
                        </div>
                        <div style={{ fontSize: 12, color: '#8E8E93', marginTop: 4 }}>
                          入库 {b.post_count} 帖
                        </div>
                        {b.oldest_post_at && b.newest_post_at ? (
                          <div style={{ fontSize: 11, color: '#AEAEB2', marginTop: 4 }}>
                            发帖 {fmtTime(b.oldest_post_at).slice(0, 10)} ~ {fmtTime(b.newest_post_at).slice(0, 10)}
                          </div>
                        ) : null}
                      </Card>
                    );
                  })}
                </div>
              )}
            </Card>
          ) : null}

          {loading ? (
            <div style={{ textAlign: 'center', padding: 48 }}>
              <Spin />
            </div>
          ) : error ? (
            <Card>
              <Empty description={error} />
            </Card>
          ) : report ? (
            <>
              <Row gutter={[12, 12]}>
                <Col xs={12} sm={6}>
                  <StatCard label="分析帖数" value={report.fetched_posts ?? 0} />
                </Col>
                <Col xs={12} sm={6}>
                  <StatCard label="有效信号帖" value={report.actionable_posts ?? 0} />
                </Col>
                <Col xs={12} sm={6}>
                  <StatCard label="信号条数" value={report.signal_count ?? 0} />
                </Col>
                <Col xs={12} sm={6}>
                  <StatCard label="日共识" value={report.consensus_count ?? 0} />
                </Col>
              </Row>

              <Card size="small" styles={{ body: { padding: 12 } }}>
                <Text type="secondary" style={{ fontSize: 12 }}>
                  {scope === SCOPE_BATCH
                    ? `批次入库 ${fmtTime(report.batch_fetched_at)} · 本批 ${report.batch_post_count ?? 0} 帖`
                    : report.cache_full
                      ? `全量缓存 ${report.fetched_posts ?? 0} 帖 · 跨度 ${report.window_days ?? cacheDays ?? '—'} 天 · ${fmtTime(report.window_start)} ~ ${fmtTime(report.window_end)}`
                      : `窗口 ${report.window_days ?? 63} 天 · ${fmtTime(report.window_start)} ~ ${fmtTime(report.window_end)}`}
                  {' · '}
                  报告生成 {fmtTime(report.generated_at)}
                  {report.source === 'ai_precomputed' ? (
                    <>
                      {' · '}
                      <Text type="success" style={{ fontSize: 12 }}>
                        AI 语义分析
                        {report.ai_analyzed_at ? ` · ${fmtTime(report.ai_analyzed_at)}` : ''}
                        {report.ai_status === 'partial'
                          ? ` · 增量进行中（已分析 ${report.actionable_posts ?? 0}/${report.fetched_posts ?? 0} 帖）`
                          : ''}
                      </Text>
                    </>
                  ) : null}
                </Text>
              </Card>

              <Card title="热门标的" size="small">
                <Table
                  rowKey="ticker"
                  size="small"
                  pagination={{ pageSize: 15, showSizeChanger: false }}
                  dataSource={report.top_tickers || []}
                  columns={columns}
                  locale={{ emptyText: '暂无标的信号' }}
                  scroll={{ x: 480 }}
                />
              </Card>

              {buyChips.length > 0 ? (
                <Card title="买入共识（按日）" size="small">
                  <Space size={[8, 8]} wrap>
                    {buyChips.map((item) => (
                      <Tag key={`${item.date}-${item.ticker}`} color="success">
                        {item.date} · ${item.ticker}
                      </Tag>
                    ))}
                  </Space>
                </Card>
              ) : null}
            </>
          ) : (
            <Empty description="暂无报告" />
          )}

          <Text type="secondary" style={{ fontSize: 12, textAlign: 'center', display: 'block' }}>
            仅供研究参考，不构成投资建议 · 数据来自 MySQL cache_data
          </Text>
        </Space>
      </div>
    </div>
  );
}

export default StockDetectReport;
