import React from 'react';
import { Card, Row, Col, Button, message } from 'antd';
import { RightOutlined, LogoutOutlined } from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import request from '../utils/request';

function RiskControl() {
  const navigate = useNavigate();

  const handleMathProofClick = () => {
    navigate('/math-proof');
  };

  const handleDonationClick = () => {
    navigate('/more');
  };

  const handleLowBuyStrategyClick = () => {
    navigate('/option-calculator/low-buy');
  };

  const handleHighSellStrategyClick = () => {
    const token = localStorage.getItem('token');
    if (!token) {
      message.error('请先登录');
      window.location.hash = '#/login';
      return;
    }
    navigate('/option-calculator/high-sell');
  };

  const handleLogout = async () => {
    try {
      await request('/api/auth/logout', { method: 'POST' });
    } catch (e) {
      // 忽略错误，仍清除本地并跳转
    }
    localStorage.removeItem('token');
    window.location.hash = '#/login';
  };

  return (
    <div className="equation-tab-page">
      {/* 捐赠信息模块 */}
      <Card 
        title="捐赠信息"
        style={{ 
          margin: '16px',
          marginBottom: 24,
          borderRadius: '14px',
          boxShadow: '0 2px 8px rgba(0,0,0,0.06)',
          overflow: 'hidden'
        }}
        bodyStyle={{ padding: '12px' }}
      >
        <Row gutter={[12, 12]}>
          <Col span={24}>
            <Card
              size="small"
              hoverable
              onClick={handleDonationClick}
              style={{
                cursor: 'pointer',
                borderRadius: '12px',
                transition: 'all 0.2s ease',
              }}
              bodyStyle={{ padding: '12px' }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <span style={{ 
                  fontSize: '15px', 
                  color: '#1C1C1E'
                }}>按月捐赠作者</span>
                <RightOutlined style={{ 
                  fontSize: '16px', 
                  color: '#AEAEB2',
                  flexShrink: 0
                }} />
              </div>
            </Card>
          </Col>
        </Row>
      </Card>

      {/* 期权计算器 */}
      <Card
        title="期权计算器"
        style={{
          margin: '16px',
          marginBottom: 24,
          borderRadius: '8px',
          overflow: 'hidden',
        }}
        bodyStyle={{ padding: '12px' }}
      >
        <Row gutter={[12, 12]}>
          <Col span={24}>
            <Card
              size="small"
              hoverable
              onClick={handleLowBuyStrategyClick}
              style={{
                cursor: 'pointer',
                borderRadius: '12px',
                transition: 'all 0.2s ease',
              }}
              bodyStyle={{ padding: '12px' }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <span style={{ fontSize: '15px', color: '#1C1C1E' }}>低买策略</span>
                <RightOutlined style={{ fontSize: '16px', color: '#AEAEB2', flexShrink: 0 }} />
              </div>
            </Card>
          </Col>
          <Col span={24}>
            <Card
              size="small"
              hoverable
              onClick={handleHighSellStrategyClick}
              style={{
                cursor: 'pointer',
                borderRadius: '12px',
                transition: 'all 0.2s ease',
              }}
              bodyStyle={{ padding: '12px' }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <span style={{ fontSize: '15px', color: '#1C1C1E' }}>高卖策略</span>
                <RightOutlined style={{ fontSize: '16px', color: '#AEAEB2', flexShrink: 0 }} />
              </div>
            </Card>
          </Col>
        </Row>
      </Card>

      {/* 数学推导模块 */}
      <Card
        title="数学推导"
        style={{
          margin: '16px',
          marginBottom: 24,
          borderRadius: '8px',
          overflow: 'hidden',
        }}
        bodyStyle={{ padding: '12px' }}
      >
        <Row gutter={[12, 12]}>
          <Col span={24}>
            <Card
              size="small"
              hoverable
              onClick={handleMathProofClick}
              style={{
                cursor: 'pointer',
                borderRadius: '12px',
                transition: 'all 0.2s ease',
              }}
              bodyStyle={{ padding: '12px' }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <span style={{ fontSize: '15px', color: '#1C1C1E' }}>期权备兑策略的盈利性证明</span>
                <RightOutlined style={{ fontSize: '16px', color: '#AEAEB2', flexShrink: 0 }} />
              </div>
            </Card>
          </Col>
        </Row>
      </Card>

      {/* 退出登录 */}
      <Card
        style={{
          margin: '16px',
          marginBottom: 24,
          borderRadius: '8px',
          overflow: 'hidden',
        }}
        bodyStyle={{ padding: '12px' }}
      >
        <Button
          type="default"
          danger
          block
          icon={<LogoutOutlined />}
          onClick={handleLogout}
        >
          退出登录
        </Button>
      </Card>
    </div>
  );
}

export default RiskControl; 
