// 数量基数（与后端 gridTradeQtyBase 一致）：每腿实际下单数量 = 基数 × 倍数。
const KIND_BASE_QTY = { stock: 100, option: 1, future: 1 };
const KIND_QTY_UNIT = { stock: '股', option: '张', future: '手' };

// qtyLabel 本地展示数量（与后端 gridTradeQtyLabel 同口径）。
function qtyLabel(kind, mult) {
  const m = Math.max(1, Math.floor(Number(mult) || 1));
  const base = KIND_BASE_QTY[kind] || KIND_BASE_QTY.stock;
  const unit = KIND_QTY_UNIT[kind] || '股';
  if (m === 1) return `${base} ${unit}`;
  return `${base * m} ${unit}（${base} ${unit} × ${m}）`;
}

