function num(v, d = 2) {
  if (v === undefined || v === null || v === '' || Number.isNaN(Number(v))) return '-';
  return Number(v).toFixed(d);
}

// 富途账户风险标签（与后端 FutuRiskStatusLabel / FutuRiskLevelLabel 同口径）。
const FUTU_RISK_STATUS_LABELS = {
  1: '非常安全',
  2: '安全',
  3: '较安全',
  4: '较低风险',
  5: '中等风险',
  6: '较高风险',
  7: '预警',
  8: '预警',
  9: '预警',
};
const FUTU_RISK_LEVEL_LABELS = { 0: '安全', 1: '预警', 2: '危险', 3: '绝对安全', 4: '危险（期权）' };

function riskStatusLabel(code) {
  return FUTU_RISK_STATUS_LABELS[Number(code)] || '未知';
}

function riskLevelLabel(code) {
  return FUTU_RISK_LEVEL_LABELS[Number(code)] || '未知';
}

// formatAge 把秒数转成「x 分钟 / x 小时 / x 天」用于展示挂单时长。
function formatAge(secs) {
  const s = Number(secs) || 0;
  if (s <= 0) return '刚刚';
  if (s < 3600) return `${Math.max(1, Math.floor(s / 60))} 分钟`;
  if (s < 86400) return `${Math.floor(s / 3600)} 小时`;
  return `${Math.floor(s / 86400)} 天`;
}

// codeShapeError 客户端轻量形状校验（与后端 gridTradeVerifyCodeShape 同口径）：
// 代码形态明确是期货（月份 YYMM / 主连 main）但类型选了别的 → 直接提示，省一次网络往返。
function codeShapeError(code, kind) {
  const body = String(code || '').includes('.') ? String(code).split('.').slice(1).join('.') : String(code || '');
  if (!body) return '';
  const isFutureShape = /(^|[^a-z])main$/i.test(body) || /^[A-Za-z]{1,6}\d{4}$/.test(body);
  if (isFutureShape && kind !== 'future') {
    return `${code} 看起来是期货合约（月份 YYMM / 主连 main），请把「类型」改为「期货」后再添加`;
  }
  return '';
}

// confirmPendingOrderChange 修改配置前的二次确认：富途上的未成交挂单不会被自动撤销。
// （产品约定：改配置是有代价的，善后由用户自己在富途客户端完成。）
function confirmPendingOrderChange(row) {
  return new Promise((resolve) => {
    Modal.confirm({
      title: '该策略在富途仍有未成交挂单',
      okText: '我已了解，继续修改',
      cancelText: '取消',
      okButtonProps: { danger: true },
      width: 480,
      content: (
        <div style={{ fontSize: 12, lineHeight: '20px' }}>
          <div>
            在途挂单：<strong>{row.pending_side_label}</strong> {row.pending_qty} @ {num(row.pending_price, 4)}
            {row.pending_order_id ? `（订单 ${row.pending_order_id}）` : ''}
            {row.pending_status ? ` 状态 ${row.pending_status}` : ''}
          </div>
          <div style={{ marginTop: 6, color: '#ff4d4f' }}>
            ⚠️ 修改区间/方向<strong>不会自动撤销该挂单</strong>。它会继续留在富途等成交；
            如需撤销，请自行到富途客户端处理（否则成交后与新的网格参数不一致）。
          </div>
        </div>
      ),
      onOk: () => resolve(true),
      onCancel: () => resolve(false),
    });
  });
}

function GridTradeStrategy({ embedded = false } = {}) {
  // 窄屏（手机）：卡片头部右上角的「刷新 / 新增策略」会被挤压甚至挤出可视区，
  // 因此在窄屏下不再放在 Card.extra，改为渲染在卡片正文顶部（见下方 mobileActions）。
  const screens = Grid.useBreakpoint();
  const isNarrowScreen = screens.md === false;

  const [loading, setLoading] = useState(false);
  const [items, setItems] = useState([]);
  const [trades, setTrades] = useState([]);
  const [drafts, setDrafts] = useState({});
  const [savingMap, setSavingMap] = useState({});
  const [deletingMap, setDeletingMap] = useState({});

  // 权限：由后端权威判定（root=100002001 绑定服务器 OpenD 券商账户）。
  // null = 尚未从接口确认（初始加载中）。
  const [hasPermission, setHasPermission] = useState(null);
  const [leverage, setLeverage] = useState(null);
  const canEdit = hasPermission === true;

  // 杠杆口径明细默认折叠（点击展开），避免长文案占屏
  const [levDetailOpen, setLevDetailOpen] = useState(false);

  // 新增表单
  const [addOpen, setAddOpen] = useState(false);
  const [adding, setAdding] = useState(false);
  const [hideInvalidated, setHideInvalidated] = useState(false);
  const [addForm, setAddForm] = useState({
    futu_code: '', kind: 'stock', direction: 'buy', lower_price: '', upper_price: '', qty_multiplier: 1,
  });

  const fetchAll = useCallback(async () => {
    setLoading(true);
    try {
      const cfgRes = await request('/api/risk-control/grid-trade/config', { method: 'GET' });
      const perm = !!cfgRes?.data?.has_permission;
      setHasPermission(perm);
      setLeverage(cfgRes?.data?.leverage || null);
      if (!perm) {
        // 无权限：不查行情/台账，直接展示空态
        setItems([]);
        setDrafts({});
        setTrades([]);
        return;
      }
      const rows = cfgRes?.data?.items || [];
      setItems(rows);
      const next = {};
      rows.forEach((row) => {
        next[row.futu_code] = {
          direction: row.direction,
          lower_price: row.lower_price ? String(row.lower_price) : '',
          upper_price: row.upper_price ? String(row.upper_price) : '',
          qty_multiplier: row.qty_multiplier >= 1 ? row.qty_multiplier : 1,
        };
      });
      setDrafts(next);

      const tradeRes = await request('/api/risk-control/grid-trade/trades?limit=100', { method: 'GET' });
      setTrades(tradeRes?.data || []);
    } catch (e) {
      message.error(e?.message || '读取单网格策略失败');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchAll();
  }, [fetchAll]);

  const updateDraft = (code, field, value) => {
    setDrafts((prev) => ({
      ...prev,
      [code]: { ...(prev[code] || {}), [field]: value },
    }));
  };

  const validateBounds = (lower, upper) => {
    const lo = Number(lower);
    const up = Number(upper);
    if (!Number.isFinite(lo) || lo <= 0) return '下区间必须为正数';
    if (!Number.isFinite(up) || up <= 0) return '上区间必须为正数';
    if (up <= lo) return '上区间必须大于下区间';
    return '';
  };

  // validateMultiplier 数量倍数必须是 ≥1 的整数（与后端校验同口径，省一次网络往返）。
  const validateMultiplier = (mult) => {
    const m = Number(mult);
    if (!Number.isInteger(m) || m < 1) {
      return '数量倍数必须是 ≥1 的整数（下单数量 = 基数 × 倍数）';
    }
    return '';
  };

  const handleAdd = async () => {
    const code = String(addForm.futu_code || '').trim();
    if (!code) {
      message.error('请输入富途代码');
      return;
    }
    const shapeErr = codeShapeError(code, addForm.kind);
    if (shapeErr) {
      message.error(shapeErr, 6);
      return;
    }
    const err = validateBounds(addForm.lower_price, addForm.upper_price);
    if (err) {
      message.error(err);
      return;
    }
    const multErr = validateMultiplier(addForm.qty_multiplier);
    if (multErr) {
      message.error(multErr);
      return;
    }
    setAdding(true);
    try {
      const res = await request('/api/risk-control/grid-trade/config', {
        method: 'PUT',
        body: JSON.stringify({
          futu_code: code,
          kind: addForm.kind,
          direction: addForm.direction,
          lower_price: Number(addForm.lower_price),
          upper_price: Number(addForm.upper_price),
          qty_multiplier: Number(addForm.qty_multiplier),
          enabled: true,
        }),
      });
      if (res?.code === 200) {
        const warn = res?.data?.warning;
        if (warn) {
          message.warning(`已新增策略 ${code}：${warn}`, 8);
        } else {
          message.success(`已新增策略 ${code}`);
        }
        setAddForm((prev) => ({
          futu_code: '', kind: prev.kind, direction: prev.direction, lower_price: '', upper_price: '', qty_multiplier: 1,
        }));
        setAddOpen(false);
        fetchAll();
      } else {
        message.error(res?.message || '新增失败', 6);
      }
    } catch (e) {
      message.error(e?.message || '新增失败', 6);
    } finally {
      setAdding(false);
    }
  };

  const handleSave = async (row) => {
    const draft = drafts[row.futu_code] || {};
    const err = validateBounds(draft.lower_price, draft.upper_price);
    if (err) {
      message.error(err);
      return;
    }
    const multErr = validateMultiplier(draft.qty_multiplier || row.qty_multiplier || 1);
    if (multErr) {
      message.error(multErr);
      return;
    }
    // 有在途挂单时：修改参数不会自动撤单，必须让用户确认自己处理
    if (row.has_pending_order) {
      const goOn = await confirmPendingOrderChange(row);
      if (!goOn) return;
    }
    setSavingMap((prev) => ({ ...prev, [row.futu_code]: true }));
    try {
      const res = await request('/api/risk-control/grid-trade/config', {
        method: 'PUT',
        body: JSON.stringify({
          futu_code: row.futu_code,
          kind: row.kind,
          direction: draft.direction || row.direction,
          lower_price: Number(draft.lower_price),
          upper_price: Number(draft.upper_price),
          qty_multiplier: Number(draft.qty_multiplier || row.qty_multiplier || 1),
          enabled: row.enabled,
        }),
      });
      if (res?.code === 200) {
        message.success('保存成功');
        fetchAll();
      } else {
        message.error(res?.message || '保存失败');
      }
    } catch (e) {
      message.error(e?.message || '保存失败');
    } finally {
      setSavingMap((prev) => ({ ...prev, [row.futu_code]: false }));
    }
  };

  const handleToggle = async (row, enabled) => {
    const draft = drafts[row.futu_code] || {};
    // 关闭策略时若有在途挂单：提醒不会自动撤单
    if (!enabled && row.has_pending_order) {
      const goOn = await new Promise((resolve) => {
        Modal.confirm({
          title: '关闭策略不会撤销在途挂单',
          okText: '我已了解，仍然关闭',
          cancelText: '取消',
          okButtonProps: { danger: true },
          width: 460,
          content: (
            <div style={{ fontSize: 12, lineHeight: '20px' }}>
              <div>
                该策略在富途仍有未成交挂单
                {row.pending_order_id ? `（订单 ${row.pending_order_id}：${row.pending_side_label} ${num(row.pending_qty, 0)} @ ${num(row.pending_price, 4)}）` : ''}
                。
              </div>
              <div style={{ marginTop: 6, color: '#ff4d4f' }}>
                ⚠️ 关闭后系统只停止<strong>挂新单</strong>（在途挂单仍会被同步成交），该挂单仍会在富途等成交；如需撤销请自行到富途客户端处理。
              </div>
            </div>
          ),
          onOk: () => resolve(true),
          onCancel: () => resolve(false),
        });
      });
      if (!goOn) return;
    }
    setSavingMap((prev) => ({ ...prev, [row.futu_code]: true }));
    try {
      const res = await request('/api/risk-control/grid-trade/config', {
        method: 'PUT',
        body: JSON.stringify({
          futu_code: row.futu_code,
          kind: row.kind,
          direction: draft.direction || row.direction,
          lower_price: Number(draft.lower_price || row.lower_price),
          upper_price: Number(draft.upper_price || row.upper_price),
          qty_multiplier: Number(draft.qty_multiplier || row.qty_multiplier || 1),
          enabled,
        }),
      });
      if (res?.code === 200) {
        message.success(enabled ? '已启用（将按当前阶段挂单）' : '已关闭（不再挂新单；在途挂单需自行到富途撤单）', 5);
        fetchAll();
      } else {
        message.error(res?.message || '操作失败');
      }
    } catch (e) {
      message.error(e?.message || '操作失败');
    } finally {
      setSavingMap((prev) => ({ ...prev, [row.futu_code]: false }));
    }
  };

  const handleDelete = async (row) => {
    setDeletingMap((prev) => ({ ...prev, [row.futu_code]: true }));
    try {
      const res = await request(
        `/api/risk-control/grid-trade/config?futu_code=${encodeURIComponent(row.futu_code)}`,
        { method: 'DELETE' },
      );
      if (res?.code === 200) {
        message.success(`已删除策略 ${row.futu_code}：历史成交记录已置为失效；如有未平持仓请到富途客户端手动清空`);
        fetchAll();
      } else {
        message.error(res?.message || '删除失败');
      }
    } catch (e) {
      message.error(e?.message || '删除失败');
    } finally {
      setDeletingMap((prev) => ({ ...prev, [row.futu_code]: false }));
    }
  };

  const columns = [
    { title: '富途代码', dataIndex: 'futu_code', key: 'futu_code', width: 170 },
    {
      title: '类型',
      dataIndex: 'kind_label',
      key: 'kind_label',
      width: 80,
      render: (v) => <Tag>{v || '-'}</Tag>,
    },
    {
      title: '方向（初始腿）',
      dataIndex: 'direction',
      key: 'direction',
      width: 130,
      render: (v, row) => (
        <Select
          value={(drafts[row.futu_code] || {}).direction || v}
          onChange={(val) => updateDraft(row.futu_code, 'direction', val)}
          options={DIRECTION_OPTIONS}
          disabled={!canEdit}
          style={{ width: '100%' }}
          size="small"
        />
      ),
    },
    {
      title: '下区间（挂买单价）',
      dataIndex: 'lower_price',
      key: 'lower_price',
      width: 150,
      render: (v, row) => (
        <Input
          type="number"
          size="small"
          value={(drafts[row.futu_code] || {}).lower_price ?? String(v)}
          onChange={(e) => updateDraft(row.futu_code, 'lower_price', e.target.value)}
          disabled={!canEdit}
        />
      ),
    },
    {
      title: '上区间（挂卖单价）',
      dataIndex: 'upper_price',
      key: 'upper_price',
      width: 150,
      render: (v, row) => (
        <Input
          type="number"
          size="small"
          value={(drafts[row.futu_code] || {}).upper_price ?? String(v)}
          onChange={(e) => updateDraft(row.futu_code, 'upper_price', e.target.value)}
          disabled={!canEdit}
        />
      ),
    },
    {
      title: '数量（基数×倍数）',
      dataIndex: 'qty_multiplier',
      key: 'qty_multiplier',
      width: 140,
      render: (v, row) => {
        const draft = (drafts[row.futu_code] || {});
        const mult = draft.qty_multiplier ?? (v >= 1 ? v : 1);
        return (
          <div style={{ fontSize: 12, lineHeight: '18px' }}>
            <InputNumber
              size="small"
              min={1}
              step={1}
              precision={0}
              value={mult}
              onChange={(val) => updateDraft(row.futu_code, 'qty_multiplier', val === null ? 1 : val)}
              disabled={!canEdit}
              style={{ width: 72 }}
            />
            <span style={{ color: '#888', marginLeft: 4 }}>{qtyLabel(row.kind, mult)}</span>
          </div>
        );
      },
    },
    {
      title: '现价（区间判断用）',
      dataIndex: 'latest_price',
      key: 'latest_price',
      align: 'right',
      width: 120,
      render: (v, row) => {
        if (!row.price_ok) {
          return <span style={{ color: '#999', fontSize: 12 }}>无行情</span>;
        }
        // 期权为模拟成交价（0.7×买价+0.3×卖价），股票/期货为快照最新价；
        // CME 期货在富途无行情权限时回退 Yahoo 主连价（口径会注明，见后端 price_source）。
        const src = row.price_source || '';
        const srcLabel = src.startsWith('模拟成交价') ? '模拟成交价' : (src.includes('主连') ? '主连价·Yahoo' : '最新价');
        return (
          <div style={{ fontSize: 12, lineHeight: '16px' }}>
            <div>{num(v, 4)}</div>
            <div style={{ color: '#888', fontSize: 11 }}>{srcLabel}</div>
          </div>
        );
      },
    },
    {
      title: '当前阶段',
      dataIndex: 'phase',
      key: 'phase',
      width: 220,
      render: (v, row) => {
        if (row.cooldown_left_sec > 0) {
          return (
            <span>
              <Tag color="red">冷却中 {Math.ceil(row.cooldown_left_sec / 60)} 分钟</Tag>
              {row.last_failed_reason ? (
                <div style={{ fontSize: 11, color: '#ff4d4f' }}>{row.last_failed_reason}</div>
              ) : null}
            </span>
          );
        }
        if (row.has_pending_order) {
          return <Tag color="processing">挂单中：{row.pending_side_label} {num(row.pending_price, 4)} 待成交</Tag>;
        }
        const isBuy = v === 'waiting_buy';
        const tag = <Tag color={isBuy ? 'red' : 'green'}>{isBuy ? '待挂买单' : '待挂卖单'}</Tag>;
        // 区间闸门：现价不在 [下区间, 上区间] 内时不会挂单，把原因显示出来
        if (row.enabled && !row.in_range) {
          return (
            <span>
              {tag}
              <div style={{ fontSize: 11, color: '#fa8c16', lineHeight: '16px' }}>
                {row.range_status || '现价不在区间内，暂不挂单'}
              </div>
            </span>
          );
        }
        return tag;
      },
    },
    {
      title: '在途挂单',
      dataIndex: 'pending_order_id',
      key: 'pending_order_id',
      width: 250,
      render: (v, row) => {
        if (!row.has_pending_order) {
          return <span style={{ color: '#999', fontSize: 12 }}>无</span>;
        }
        return (
          <div style={{ fontSize: 12, lineHeight: '18px' }}>
            <div>
              {row.pending_side_label} {num(row.pending_qty, 0)} @ {num(row.pending_price, 4)}
              {row.pending_filled_qty > 0 ? `（已成交 ${num(row.pending_filled_qty, 0)}）` : ''}
            </div>
            <div style={{ color: '#888' }}>
              订单 {v || '-'} · {row.pending_status || 'Submitted'}
            </div>
            <div style={{ color: '#faad14' }}>
              已挂 {formatAge(row.pending_age_sec)} · 不自动撤单
            </div>
          </div>
        );
      },
    },
    {
      title: '循环',
      dataIndex: 'cycle_count',
      key: 'cycle_count',
      align: 'right',
      width: 60,
      render: (v) => v ?? 0,
    },
    {
      title: '最近成交',
      dataIndex: 'last_filled_at',
      key: 'last_filled_at',
      width: 170,
      render: (v, row) => (
        <span style={{ fontSize: 12 }}>
          {v
            ? `${row.last_filled_side_label || ''} ${num(row.last_filled_price, 4)} · ${v}`
            : '尚未成交'}
        </span>
      ),
    },
    {
      title: '启用',
      dataIndex: 'enabled',
      key: 'enabled',
      width: 70,
      render: (v, row) => (
        <Switch
          checked={v}
          size="small"
          disabled={!canEdit || !!savingMap[row.futu_code]}
          loading={!!savingMap[row.futu_code]}
          onChange={(checked) => handleToggle(row, checked)}
        />
      ),
    },
    {
      title: '操作',
      key: 'actions',
      width: 150,
      render: (_, row) => (
        <span>
          <Button
            type="link"
            size="small"
            icon={<SaveOutlined />}
            loading={!!savingMap[row.futu_code]}
            disabled={!canEdit}
            onClick={() => handleSave(row)}
          >
            保存
          </Button>
          <Popconfirm
            title="确认删除该策略？"
            okText="确认删除"
            cancelText="取消"
            okButtonProps={{ danger: true }}
            onConfirm={() => handleDelete(row)}
            description={(
              <div style={{ maxWidth: 340, fontSize: 12, lineHeight: '20px' }}>
                <div>1. 该策略的历史成交记录会标记为<strong>「已失效」</strong>（保留留痕，但不再参与循环）。</div>
                <div>2. 删除后系统<strong>不再跟踪</strong>该标的的持仓与循环；重新添加同一代码视为<strong>全新开始</strong>。</div>
                {row.has_pending_order && (
                  <div style={{ color: '#ff4d4f' }}>
                    3. ⚠️ 该策略在富途仍有<strong>未成交挂单</strong>
                    {row.pending_order_id ? `（订单 ${row.pending_order_id}：${row.pending_side_label} ${num(row.pending_qty, 0)} @ ${num(row.pending_price, 4)}）` : ''}
                    ，删除<strong>不会自动撤销</strong>，请自行到富途客户端撤单。
                  </div>
                )}
                <div style={{ color: '#ff4d4f' }}>
                  {row.has_pending_order ? '4. ' : '3. '}
                  ⚠️ 若此前已买入但尚未卖出，删除后请<strong>自行到富途客户端手动清空持仓</strong>，系统不会代你平仓。
                </div>
              </div>
            )}
          >
            <Button
              type="link"
              size="small"
              danger
              icon={<DeleteOutlined />}
              loading={!!deletingMap[row.futu_code]}
              disabled={!canEdit}
            >
              删除
            </Button>
          </Popconfirm>
        </span>
      ),
    },
  ];

  const tradeColumns = [
    { title: '时间', dataIndex: 'created_at_str', key: 'created_at_str', width: 150 },
    { title: '代码', dataIndex: 'futu_code', key: 'futu_code', width: 160 },
    {
      title: '方向',
      dataIndex: 'side',
      key: 'side',
      width: 60,
      render: (v) => (
        <Tag color={v === 'buy' ? 'red' : 'green'}>{v === 'buy' ? '买' : '卖'}</Tag>
      ),
    },
    {
      title: '类型',
      dataIndex: 'kind',
      key: 'kind',
      width: 60,
      render: (v) => {
        const map = { stock: '股票', option: '期权', future: '期货' };
        return map[v] || v || '-';
      },
    },
    { title: '数量', dataIndex: 'qty', key: 'qty', align: 'right', width: 70 },
    { title: '挂单价', dataIndex: 'price', key: 'price', align: 'right', width: 90, render: (v) => num(v, 4) },
    { title: '订单号', dataIndex: 'order_id', key: 'order_id', width: 110, render: (v) => (v ? String(v) : '-') },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      width: 110,
      render: (v, row) => {
        const map = {
          placed: { color: 'processing', label: '挂单中' },
          filled: { color: 'green', label: '已成交' },
          failed: { color: 'red', label: '失败' },
          canceled: { color: 'default', label: '已撤/废单' },
        };
        const m = map[v] || { color: 'default', label: v || '-' };
        return (
          <span>
            <Tag color={m.color}>{m.label}</Tag>
            {row.order_status ? <div style={{ fontSize: 11, color: '#888' }}>{row.order_status}</div> : null}
          </span>
        );
      },
    },
    {
      title: '成交量/均价',
      dataIndex: 'filled_qty',
      key: 'filled_qty',
      align: 'right',
      width: 110,
      render: (v, row) => (
        <span style={{ fontSize: 12 }}>
          {Number(v) > 0 ? `${num(v, 0)} @ ${num(row.dealt_avg_price, 4)}` : '-'}
        </span>
      ),
    },
    {
      title: '成交时间',
      dataIndex: 'filled_at_str',
      key: 'filled_at_str',
      width: 150,
      render: (v) => <span style={{ fontSize: 12 }}>{v || '-'}</span>,
    },
    {
      title: '记录有效性',
      dataIndex: 'invalidated',
      key: 'invalidated',
      width: 100,
      render: (v, row) => (
        v
          ? <Tag color="default">已失效</Tag>
          : <Tag color="blue">有效</Tag>
      ),
    },
    { title: '原因', dataIndex: 'reason', key: 'reason', ellipsis: true },
  ];

  return (
    <div className={embedded ? undefined : 'equation-tab-page'} style={{ paddingBottom: embedded ? 0 : 24 }}>
      {/* ---------- 权限状态（置顶） ---------- */}
      {hasPermission === true && (
        <Alert
          type="success"
          showIcon
          style={{ margin: '16px', marginBottom: 12, borderRadius: 8 }}
          message="当前账号有权限：单网格交易已启用（root 账号绑定服务器富途 OpenD 券商账户）"
        />
      )}
      {hasPermission === false && (
        <Alert
          type="error"
          showIcon
          style={{ margin: '16px', marginBottom: 12, borderRadius: 8 }}
          message="当前账号无权限：单网格买卖策略仅对 root 用户开放"
          description="服务器上的富途 OpenD 券商账户仅绑定 root 用户（其他账号没有对应的港美股券商通道），因此本功能不对普通账号开放。以下为只读空态，所有操作均已禁用。"
        />
      )}

      {/* ---------- 账户风险闸门（富途口径，买入风控） ---------- */}
      {leverage && (
        <Alert
          type={leverage.error ? 'warning' : leverage.ok ? 'success' : 'error'}
          showIcon
          style={{ margin: '16px', marginBottom: 12, borderRadius: 8 }}
          message={(() => {
            if (leverage.error) {
              return `账户风险闸门：无法获取（${leverage.error}）—— 买入挂单会被拦截`;
            }
            const st = Number(leverage.max_risk_status) || 0;
            const stLabel = leverage.max_risk_status_label || '未知';
            const lim = Number(leverage.risk_limit) || 6;
            return (
              <span>
                账户风险闸门（富途口径）
                <strong style={{ fontSize: 15 }}>
                  {st > 0 ? ` 证券风险 LEVEL${st}（${stLabel}）` : ' 未返回证券风险等级'}
                </strong>
                <span style={{ color: '#888' }}>（上限 LEVEL{lim}，买入前校验）</span>
                {leverage.ok ? '：未触发，可自动买入' : '：已达门槛，自动买入已暂停'}
              </span>
            );
          })()}
          description={(() => {
            if (leverage.error) {
              return '买入前需校验富途账户风险，取不到数据时按「不允许买入」处理（fail-closed）。请确认 OpenD 交易解锁状态。';
            }
            const lim = Number(leverage.risk_limit) || 6;
            const excess = Number(leverage.excess_liquidity) || 0;
            const refLev = Number(leverage.value);
            const exposure = Number(leverage.total_exposure) || 0;
            // 杠杆口径 = 证券账户持仓市值（证券+基金+债券）÷ 净资产（富途 App「风险水平 → 杠杆倍数」）
            const secNet = Number(leverage.securities_net_assets) || 0;
            const secHoldings = Number(leverage.securities_holdings) || 0;
            const secCash = Number(leverage.securities_cash) || 0;
            const secDebt = Number(leverage.securities_debt) || 0;
            const secFrozen = Number(leverage.securities_frozen_cash) || 0;
            const levText = Number.isFinite(refLev) && refLev > 0 ? refLev.toFixed(3) : '-';
            const excessOf = (d) =>
              d.market === 'Futures'
                ? Number(d.available_funds) || 0
                : (Number(d.total_assets) || 0) - (Number(d.maintenance_margin) || 0);
            const parts = (leverage.details || []).map((d) => {
              const risk = d.market === 'Futures'
                ? `risk_level ${Number(d.risk_level) || 0}（${riskLevelLabel(d.risk_level)}）`
                : `risk_status ${Number(d.risk_status) || 0}（${riskStatusLabel(d.risk_status)}）`;
              return `${d.market}: ${risk} / 维持保证金 ${num(d.maintenance_margin, 0)} / 剩余流动性 ${num(excessOf(d), 0)} / 净资产 ${num(d.total_assets, 0)} / 证券市值 ${num(d.market_val, 0)} / 基金 ${num(d.fund_assets, 0)} / 现金 ${num(d.cash, 0)} / 冻结 ${num(d.frozen_cash, 0)} / 融资 ${num(d.debt_cash, 0)}${d.currency ? `（${d.currency}）` : ''}`;
            });
            return (
              <div style={{ fontSize: 12, lineHeight: '19px', overflowWrap: 'anywhere' }}>
                <div>
                  依据富途账户风险字段：证券 risk_status ≤ LEVEL{lim}、期货 risk_level 非预警/危险、剩余流动性 &gt; 0。
                  <Button
                    type="link"
                    size="small"
                    style={{ padding: 0, marginLeft: 8, height: 'auto', fontSize: 12 }}
                    onClick={() => setLevDetailOpen((v) => !v)}
                  >
                    {levDetailOpen ? '收起明细 ▲' : '展开明细 ▼'}
                  </Button>
                </div>
                <div style={{ marginTop: 2 }}>
                  证券账户综合杠杆 <strong style={{ fontSize: 14 }}>{levText}x</strong>
                  <span style={{ color: '#888' }}>
                    （= 持仓市值 {num(secHoldings, 0)}（证券+基金+债券）÷ 净资产 {num(secNet, 0)}
                    ；现金 {num(secCash, 0)} 不计入分子）
                  </span>
                  {secFrozen > 0 && (
                    <span style={{ color: '#faad14' }}>
                      　港股新股认购等冻结资金 {num(secFrozen, 0)}、融资欠款 {num(secDebt, 0)} 均不参与杠杆
                    </span>
                  )}
                </div>
                {levDetailOpen && (
                  <div style={{ lineHeight: '19px', overflowWrap: 'anywhere' }}>
                    <div>
                      合计剩余流动性 {num(excess, 0)}
                      ，含期货总敞口 {num(exposure, 0)}（敞口/净资产 {(Number(leverage.exposure_ratio) || 0).toFixed(3)}）
                      ，计价币种：{leverage.currency || 'HKD'}（可用 FUTU_GRID_TRADE_FUNDS_CURRENCY 调整）
                    </div>
                    {parts.length > 0 && <div style={{ color: '#888', wordBreak: 'break-all' }}>各账户：[{parts.join('；')}]</div>}
                    {leverage.mixed_currency && (
                      <div style={{ color: '#faad14' }}>
                        ⚠️ 各账户返回币种不一致（{(leverage.currencies || []).join('/')}），聚合数值可能混币种，建议统一计价币种。
                      </div>
                    )}
                  </div>
                )}
                {!leverage.ok && (
                  <div style={{ color: '#ff4d4f' }}>
                    {leverage.reason ? `${leverage.reason}。` : ''}降低融资或减仓后会自动恢复挂单。
                  </div>
                )}
              </div>
            );
          })()}
        />
      )}

      {/* ---------- 策略说明 ---------- */}
      <Card
        title="单网格买卖策略"
        style={{ margin: '16px', marginTop: 0, borderRadius: 8 }}
        bodyStyle={{ padding: 12 }}
        extra={isNarrowScreen ? null : (
          <span>
            <Button size="small" icon={<ReloadOutlined />} onClick={fetchAll} loading={loading} style={{ marginRight: 8 }}>
              刷新
            </Button>
            <Button
              size="small"
              type="primary"
              icon={<PlusOutlined />}
              disabled={!canEdit}
              onClick={() => setAddOpen((v) => !v)}
            >
              新增策略
            </Button>
          </span>
        )}
      >
        {/* 策略说明 + 富途代码格式速查：默认折叠，点击标题展开（桌面端/手机端一致） */}
        <Collapse
          ghost
          size="small"
          style={{ marginBottom: 12 }}
          items={[
            {
              key: 'strategy-notice',
              label: <span style={{ fontSize: 13 }}>真实挂单策略说明（点击展开）</span>,
              children: (
                <Alert
                  type="warning"
                  showIcon
                  message={STRATEGY_NOTICE_TITLE}
                  description={STRATEGY_NOTICE_DESC}
                />
              ),
            },
            {
              key: 'code-format-guide',
              label: <span style={{ fontSize: 13 }}>富途代码格式速查（新增策略前请先核对，点击展开）</span>,
              children: (
                <Row gutter={[12, 12]}>
                  {CODE_FORMAT_GUIDE.map((g) => (
                    <Col xs={24} md={8} key={g.kind}>
                      <Card
                        size="small"
                        style={{ background: 'rgba(0,0,0,0.02)' }}
                        title={(
                          <span>
                            <Tag color={g.kind === 'stock' ? 'blue' : g.kind === 'option' ? 'purple' : 'gold'}>
                              {g.label}
                            </Tag>
                            <code style={{ fontSize: 12 }}>{g.format}</code>
                          </span>
                        )}
                      >
                        <div style={{ marginBottom: 6 }}>
                          {g.examples.map((ex) => (
                            <div key={ex} style={{ fontSize: 12, lineHeight: '22px' }}>
                              <code style={{
                                padding: '1px 6px',
                                borderRadius: 4,
                                background: 'rgba(22,119,255,0.1)',
                                color: '#1677ff',
                              }}
                              >
                                {ex}
                              </code>
                            </div>
                          ))}
                        </div>
                        <div style={{ fontSize: 12, color: '#888' }}>{g.tips}</div>
                      </Card>
                    </Col>
                  ))}
                </Row>
              ),
            },
          ]}
        />

        {/* 手机端：操作按钮紧贴策略列表上方（卡片头右侧放不下会被挤压/挤出可视区） */}
        {isNarrowScreen && (
          <div style={{ display: 'flex', gap: 8, marginBottom: 12 }}>
            <Button
              size="small"
              icon={<ReloadOutlined />}
              onClick={fetchAll}
              loading={loading}
              style={{ flex: 1 }}
            >
              刷新
            </Button>
            <Button
              size="small"
              type="primary"
              icon={<PlusOutlined />}
              disabled={!canEdit}
              onClick={() => setAddOpen((v) => !v)}
              style={{ flex: 1 }}
            >
              新增策略
            </Button>
          </div>
        )}

        {/* ---------- 新增表单 ---------- */}
        {addOpen && (
          <Card type="inner" title="新增单网格策略" style={{ marginBottom: 16 }} size="small">
            <Row gutter={[12, 12]}>
              <Col xs={24} sm={7}>
                <div style={{ marginBottom: 4, color: '#666', fontSize: 13 }}>富途代码</div>
                <Input
                  placeholder={CODE_PLACEHOLDER[addForm.kind]}
                  value={addForm.futu_code}
                  onChange={(e) => setAddForm((prev) => ({ ...prev, futu_code: e.target.value }))}
                />
                <div style={{ marginTop: 4, fontSize: 12, color: '#888', lineHeight: '18px' }}>
                  {(() => {
                    const g = CODE_FORMAT_GUIDE.find((it) => it.kind === addForm.kind);
                    if (!g) return null;
                    return (
                      <span>
                        格式：<code>{g.format}</code>
                        {' ｜ 示例：'}
                        {g.examples.map((ex) => (
                          <Button
                            key={ex}
                            type="link"
                            size="small"
                            style={{ padding: 0, marginRight: 6, height: 'auto', fontFamily: 'monospace' }}
                            onClick={() => setAddForm((prev) => ({ ...prev, futu_code: ex.split('（')[0] }))}
                          >
                            {ex.split('（')[0]}
                          </Button>
                        ))}
                      </span>
                    );
                  })()}
                </div>
                <div style={{ marginTop: 2, fontSize: 12, color: '#888' }}>
                  新增时校验代码格式；挂单前需用<strong>现价</strong>判断是否落在区间内（取不到价的标的不会挂单）——期权用买卖价算模拟成交价，一般不需要单独行情卡
                </div>
              </Col>
              <Col xs={12} sm={4}>
                <div style={{ marginBottom: 4, color: '#666', fontSize: 13 }}>类型</div>
                <Select
                  value={addForm.kind}
                  options={KIND_OPTIONS}
                  onChange={(v) => setAddForm((prev) => ({ ...prev, kind: v }))}
                  style={{ width: '100%' }}
                />
              </Col>
              <Col xs={12} sm={4}>
                <div style={{ marginBottom: 4, color: '#666', fontSize: 13 }}>方向（首触发）</div>
                <Select
                  value={addForm.direction}
                  options={DIRECTION_OPTIONS}
                  onChange={(v) => setAddForm((prev) => ({ ...prev, direction: v }))}
                  style={{ width: '100%' }}
                />
              </Col>
              <Col xs={12} sm={3}>
                <div style={{ marginBottom: 4, color: '#666', fontSize: 13 }}>下区间</div>
                <InputNumber
                  style={{ width: '100%' }}
                  min={0.0001}
                  step={0.01}
                  value={addForm.lower_price === '' ? null : Number(addForm.lower_price)}
                  onChange={(v) => setAddForm((prev) => ({ ...prev, lower_price: v === null ? '' : String(v) }))}
                />
              </Col>
              <Col xs={12} sm={3}>
                <div style={{ marginBottom: 4, color: '#666', fontSize: 13 }}>上区间</div>
                <InputNumber
                  style={{ width: '100%' }}
                  min={0.0001}
                  step={0.01}
                  value={addForm.upper_price === '' ? null : Number(addForm.upper_price)}
                  onChange={(v) => setAddForm((prev) => ({ ...prev, upper_price: v === null ? '' : String(v) }))}
                />
              </Col>
              <Col xs={12} sm={3}>
                <div style={{ marginBottom: 4, color: '#666', fontSize: 13 }}>数量倍数</div>
                <InputNumber
                  style={{ width: '100%' }}
                  min={1}
                  step={1}
                  precision={0}
                  value={addForm.qty_multiplier || 1}
                  onChange={(v) => setAddForm((prev) => ({ ...prev, qty_multiplier: v === null ? 1 : Math.max(1, Math.floor(v)) }))}
                />
                <div style={{ marginTop: 4, fontSize: 12, color: '#888', lineHeight: '18px' }}>
                  实际数量：{qtyLabel(addForm.kind, addForm.qty_multiplier)}（≥1 整数）
                </div>
              </Col>
            </Row>
            <div style={{ marginTop: 12, textAlign: 'right' }}>
              <Button style={{ marginRight: 8 }} onClick={() => setAddOpen(false)}>取消</Button>
              <Button type="primary" icon={<PlusOutlined />} loading={adding} onClick={handleAdd}>
                新增
              </Button>
            </div>
          </Card>
        )}

        {/* ---------- 策略列表 ---------- */}
        <Table
          dataSource={items}
          columns={columns}
          rowKey="futu_code"
          loading={loading}
          pagination={false}
          size="small"
          scroll={{ x: 'max-content' }}
          locale={{ emptyText: '暂无单网格策略，点击上方「新增策略」' }}
        />
      </Card>

      {/* ---------- 自动交易台账 ---------- */}
      <Card
        title="自动交易记录（仅本模块自动下单）"
        style={{ margin: embedded ? '0 16px' : '16px', marginTop: 0, borderRadius: 8 }}
        bodyStyle={{ padding: 12 }}
        extra={(
          <span>
            <span style={{ marginRight: 8, fontSize: 12, color: '#888' }}>
              隐藏已失效
              <Switch
                size="small"
                style={{ marginLeft: 6 }}
                checked={hideInvalidated}
                onChange={setHideInvalidated}
              />
            </span>
            <Button size="small" icon={<ReloadOutlined />} onClick={fetchAll}>刷新</Button>
          </span>
        )}
      >
        <Table
          dataSource={hideInvalidated ? trades.filter((t) => !t.invalidated) : trades}
          columns={tradeColumns}
          rowKey="id"
          pagination={{ pageSize: 10, showSizeChanger: false }}
          size="small"
          scroll={{ x: 'max-content' }}
          locale={{ emptyText: '暂无自动交易记录' }}
        />
      </Card>
    </div>
  );
}

export default GridTradeStrategy;
